  "Google, Apple and Outlook refresh the calendar on their own – new sessions and changes can show up late (Apple: usually within an hour, Outlook: a few hours, Google: up to several hours). The app tells you straight away.": "Google, Apple i Outlook odświeżają kalendarz same, więc nowe treningi i zmiany mogą pojawić się z opóźnieniem (Apple: zwykle do godziny, Outlook: kilka godzin, Google: nawet kilkanaście godzin). Aplikacja pokazuje je od razu.",
