  "Instead of {0}": "Zamiast: {0}",
  "In this app, reminders are local notifications of your phone: they work without the internet. Allow notifications for Habcore Gym when the phone asks.": "W tej aplikacji przypomnienia są lokalnymi powiadomieniami telefonu: działają bez internetu. Gdy telefon zapyta, zezwól Habcore Gym na powiadomienia.",
  "To get reminders, install the Habcore Gym app or add this page to your phone's Home Screen.": "Żeby dostawać przypomnienia, zainstaluj aplikację Habcore Gym albo dodaj tę stronę do ekranu początkowego telefonu.",
  "A browser tab cannot send reminders. Once added, open Habcore Gym from its icon and allow notifications.": "Karta przeglądarki nie może wysyłać przypomnień. Po dodaniu otwórz Habcore Gym z ikony i zezwól na powiadomienia.",
