  "Bank 1 freeze, earned every 4 trained weeks. A missed week with no freeze banked ends the streak.": "1 zamrożenie w zapasie, zdobywane co 4 tygodnie z treningiem. Opuszczony tydzień bez zamrożenia w zapasie kończy Passę.",
  "Bank up to 2 freezes, one every 4 trained weeks. A missed week with no freeze banked ends the streak.": "Do 2 zamrożeń w zapasie, jedno co 4 tygodnie z treningiem. Opuszczony tydzień bez zamrożenia w zapasie kończy Passę.",
