  "Signed out on this phone": "Wylogowano cię na tym telefonie",
  "Signs this profile out on every device, including this one, phones too. You sign in again as usual, with your password or passkey.": "Wylogowuje ten profil na wszystkich urządzeniach, także na tym i na telefonach. Logujesz się potem jak zwykle, hasłem albo kluczem dostępu.",
