  'I explicitly consent to the processing of my health data.': 'Wyrażam wyraźną zgodę na przetwarzanie moich danych o zdrowiu.',
  'I explicitly consent to Habcore Gym processing my health data (workouts, body weight and measurements, heart rate, progress photos) to run the app. I can withdraw it by deleting my account.': 'Wyrażam wyraźną zgodę na przetwarzanie przez Habcore Gym moich danych o zdrowiu (treningi, masa i pomiary ciała, tętno, zdjęcia sylwetki) w celu działania aplikacji. Mogę ją wycofać, usuwając konto.',
  'Tick both boxes to continue.': 'Zaznacz oba pola, aby kontynuować.',
  'Terms and privacy': 'Regulamin i prywatność',
  'Habcore Gym now has Terms and a Privacy policy. Please read them and accept to keep using the app. Your data stays as it is.': 'Habcore Gym ma teraz Regulamin i Politykę prywatności. Przeczytaj je i zaakceptuj, aby dalej korzystać z aplikacji. Twoje dane zostają bez zmian.',
  "Accept and continue": "Zaakceptuj i kontynuuj",
  'Registration': 'Rejestracja',
  'Register with a passkey instead': 'Zarejestruj się kluczem dostępu',
  'Register with a password instead': 'Zarejestruj się hasłem',
  'This browser doesn\'t do passkeys, but you can still use Habcore Gym locally on this device.': 'Ta przeglądarka nie obsługuje kluczy dostępu, ale nadal możesz używać Habcore Gym lokalnie na tym urządzeniu.',
  "This browser doesn't support passkeys, and this instance requires an account. Try a browser or device with passkey support.": 'Ta przeglądarka nie obsługuje kluczy dostępu, a ten serwer wymaga konta. Spróbuj innej przeglądarki lub urządzenia z obsługą kluczy dostępu.',
  'Continue without account': 'Kontynuuj bez konta',
  'Passkeys use {0}. No passwords to remember.': 'Klucze dostępu korzystają z: {0}. Żadnych haseł do zapamiętania.',
