  'Password': 'Hasło',
  'Passkey': 'Klucz dostępu',
  'Passkeys use {0}. A password works too, where passkeys do not.': 'Klucze dostępu korzystają z: {0}. Tam, gdzie nie działają, możesz użyć hasła.',
  "This browser doesn't support passkeys. Sign in with your name and password instead.": "Ta przeglądarka nie obsługuje kluczy dostępu. Zaloguj się nazwą i hasłem.",
  'Have a reset code from your admin?': 'Masz kod resetu od administratora?',
  'Reset your password': 'Zresetuj hasło',
  "Enter the code your admin gave you and choose a new password. It signs you out everywhere else.": "Wpisz kod od administratora i wybierz nowe hasło. Zostaniesz wylogowany na wszystkich innych urządzeniach.",
  'Reset code': 'Kod resetu',
  'New password': 'Nowe hasło',
