  'Enter your password.': 'Wpisz swoje hasło.',
  'Enter the reset code.': 'Wpisz kod resetu.',
  'The two passwords are not the same.': 'Hasła nie są takie same.',
  "Set · sign in as “{0}”": "Ustawione · logujesz się jako „{0}”",
