  'Sign out everywhere': 'Wyloguj się wszędzie',
  'Account ID': 'ID konta',
  'Account ID copied': 'Skopiowano ID konta',
  'Ends this profile’s sessions on all your devices.': 'Kończy sesje tego profilu na wszystkich twoich urządzeniach.',
