  'Auto-backup on changes': 'Automatyczna kopia przy zmianach',
  "Saves a dated copy to Documents/Habcore Gym after finishing a workout or editing a routine, and keeps the newest {0}. Point a sync app at that folder, or copy it out by hand.": "Po zakończeniu treningu lub edycji planu zapisuje kopię z datą w folderze Dokumenty/Habcore Gym i zachowuje {0} najnowszych. Wskaż ten folder w aplikacji do synchronizacji albo kopiuj go ręcznie.",
  'Reset everything?': 'Zresetować wszystko?',
  'Reset everything': 'Zresetuj wszystko',
  'Deletes your plan, workouts, body weight, photos and videos on this device. This cannot be undone.': 'Usuwa plan, treningi, masę ciała, zdjęcia i filmy na tym urządzeniu. Nie można tego cofnąć.',
  'Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.': 'Usuwa plan, treningi, masę ciała, zdjęcia i filmy z profilu na tym serwerze i ze wszystkich zalogowanych urządzeń. Nie można tego cofnąć.',
  "Sync failed: the server refused the upload as too large. Your changes have not reached the server.": "Nie udało się zsynchronizować: serwer odrzucił przesyłane dane jako zbyt duże. Twoje zmiany nie dotarły na serwer.",
  "This device is out of storage: the change is not saved on it. Signed in, it still goes to the server.": "Na tym urządzeniu zabrakło miejsca: zmiana nie została na nim zapisana. Jeśli jesteś zalogowany, i tak trafi na serwer.",
