  'Imported! {0} routines are in your plan and your rotation starts over with them. See you at the next session.': { one: 'Zaimportowano {0} plan treningowy, a rotacja zaczyna się od nowa. Do zobaczenia na następnym treningu.', few: 'Zaimportowano {0} plany treningowe, a rotacja zaczyna się od nich od nowa. Do zobaczenia na następnym treningu.', many: 'Zaimportowano {0} planów treningowych, a rotacja zaczyna się od nich od nowa. Do zobaczenia na następnym treningu.', other: 'Zaimportowano {0} planów treningowych, a rotacja zaczyna się od nich od nowa. Do zobaczenia na następnym treningu.' },
  'Your rotation was set to this plan.': 'Twoja rotacja korzysta teraz z tego planu.',
  'Imported without changing your week.': 'Zaimportowano bez zmiany tygodnia.',
  "This plan was imported before the app kept proposals; only its summary is left.": "Ten plan zaimportowano, zanim aplikacja zaczęła zachowywać propozycje – zostało tylko podsumowanie.",
  "Nothing yet. Every plan, suggestion and debrief will be kept here, whether you said yes or no.": "Jeszcze nic. Każdy plan, sugestia i podsumowanie zostaną tu zachowane – niezależnie od tego, czy się zgodzisz, czy nie.",
