  'Plates': 'Talerze',
  "Pairs of each size you own. Every set row loads from this list, so a home gym with one pair of 45s is never told to use two.": "Pary talerzy każdego rozmiaru, które masz. Każdy wiersz serii korzysta z tej listy, więc domowa siłownia z jedną parą 45-tek nigdy nie dostanie polecenia, żeby użyć dwóch.",
