  "Import a photo of your membership card or scan it with the camera. No extra app needed at the gym, just open this screen.": "Zaimportuj zdjęcie karty członkowskiej lub zeskanuj ją aparatem. Na siłowni nie potrzebujesz innej aplikacji – wystarczy otworzyć ten ekran.",
