  'Couldn’t keep a copy of the changes on this device. Nothing was removed.': 'Nie udało się zachować kopii zmian na tym urządzeniu. Nic nie zostało usunięte.',
  "Not everything is on your server yet": "Nie wszystko jest jeszcze na twoim serwerze",
  "Not on your server yet: {0}": "Jeszcze nie ma na twoim serwerze: {0}",
  'Some changes on this device have not reached your server.': 'Niektóre zmiany z tego urządzenia nie dotarły jeszcze na twój serwer.',
  "Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Spróbuj ponownie albo najpierw wyeksportuj kopię zapasową. Jeśli mimo to przejdziesz dalej, kopia tych zmian zostanie na tym urządzeniu, dopóki znów nie połączy się z tym serwerem na tym koncie. Wtedy zostaną dodane z powrotem.",
  'Syncing…': 'Synchronizowanie…',
  'Try again': 'Spróbuj ponownie',
