  'Pause': 'Wstrzymaj',
  "Keep timing after target": "Mierz czas po osiągnięciu celu",
  "Timed sets continue up to 15 extra minutes. Tap Done to log the actual duration.": "Serie na czas mogą trwać do 15 minut dłużej. Dotknij „Gotowe”, żeby zapisać rzeczywisty czas.",
  'Edit workout': 'Edytuj trening',
  'Workout updated': 'Trening zaktualizowany',
  "Save workout changes?": "Zapisać zmiany w treningu?",
  "Save your edits to this workout, or keep the original record.": "Zapisz zmiany w tym treningu albo zachowaj pierwotny zapis.",
  'Save changes': 'Zapisz zmiany',
  "Don't save": 'Nie zapisuj',
  'Keep editing': 'Kontynuuj edycję',
  'This workout was deleted on another device. Your edits are still here.': 'Ten trening usunięto na innym urządzeniu. Twoje zmiany nadal są tutaj.',
  'Close editor': 'Zamknij edytor',
  'Editing a saved workout. Date and duration stay unchanged.': 'Edytujesz zapisany trening. Data i czas trwania pozostaną bez zmian.',
  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': 'Na każde wyciskanie jedno przyciąganie, żeby barki pozostały w równowadze.',
  "A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.": "Dwudniowa rotacja na trzy treningi w tygodniu, ułożona pod wskazany przez ciebie sprzęt. Najpierw ćwiczenia wielostawowe, na każde wyciskanie jedno przyciąganie, a dni pokrywają się na tyle, że nic nie zostaje bez treningu przez dwa tygodnie.",
  'Based on the training already in this demo profile.': 'Na podstawie treningów, które już są w tym profilu demo.',
  "Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.": "Masa ciała stoi w miejscu od czterech tygodni, a celem jest przybranie na wadze. To kwestia kuchni, nie treningu – to nie plan jest przeszkodą.",
  'Demo': 'Demo',
  'Demo data reset': 'Dane demo zresetowane',
  'Direct arm work, since you asked for it.': 'Bezpośrednia praca na ramiona, zgodnie z twoją prośbą.',
  "Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.": "Każda główna seria w tym ćwiczeniu przez trzy treningi wypadała na RPE 9,5 lub wyżej, a ciężar się nie ruszył. Zmiana ruchu na cztery tygodnie zwykle szybciej przełamuje taki zastój niż mozolenie się z tym samym.",
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Przykładowe dane, zapisane tylko w tej przeglądarce. Szalej i zmieniaj, co chcesz.',
  'Full body A': 'Całe ciało A',
  'Full body B': 'Całe ciało B',
  "Horizontal pressing, the other half of the session.": "Wyciskanie poziome, druga połowa treningu.",
  'Live demo. Everything stays in this browser.': 'Demo na żywo. Wszystko zostaje w tej przeglądarce.',
  "No training history yet, so starting conservatively.": "Nie ma jeszcze historii treningów, więc zaczynamy ostrożnie.",
  'Passkey sign-in, sync across your devices, your own data.': 'Logowanie kluczem dostępu, synchronizacja między twoimi urządzeniami, twoje własne dane.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Przywraca przykładowy plan, treningi i ważenia do stanu początkowego.',
  'Reset': 'Resetuj',
  'Reset demo data': 'Zresetuj dane demo',
  'Reset demo data?': 'Zresetować dane demo?',
  "Revised as you asked. Everything you did not question is exactly as it was.": "Poprawione zgodnie z prośbą. Reszta została dokładnie taka, jaka była.",
  'Same pattern, higher reps than day A.': 'Ten sam wzorzec, więcej powtórzeń niż w dniu A.',
  'Self-host it in a minute →': 'Postaw go u siebie w minutę →',
  'Self-host Habcore Gym': 'Postaw Habcore Gym u siebie',
  "Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.": "Treningi trwają około piętnastu minut za długo. To ćwiczenie dodatkowe najmniej straci na jednej serii mniej.",
  'Start the demo': 'Uruchom demo',
  "The main lower-body driver, where most of the strength comes from.": "Główny ruch na dolną część ciała – stąd bierze się większość siły.",
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Te same wzorce, inne warianty: wystarczająco wspólnego, by robić postępy, i wystarczająco różnic, by się nie nudzić.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Najpierw dwa duże wzorce: nogi i wyciskanie, póki masz świeże siły.',
  "This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the Habcore Gym server, which you get by self-hosting it.": "To demo działa w całości w twojej przeglądarce na przykładowych danych. Nic nie jest nigdzie wysyłane. Logowanie kluczem dostępu i synchronizacja między urządzeniami działają z serwerem Habcore Gym, który stawiasz u siebie.",
  "Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.": "Trzy rzeczy warte zmiany i jedna warta uwagi. Cała reszta działa: postępy w przysiadzie i przyciąganiach idą zgodnie z planem.",
  'Vertical pressing.': 'Wyciskanie pionowe.',
  "You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.": "Od trzech tygodni z rzędu przenosisz ten trening na sobotę. Lepiej wpisać to w plan, niż co tydzień go nadpisywać.",
  'You’re in the demo': 'Jesteś w wersji demo',
