  'Log your body weight to score this lift.': 'Zapisz swoją masę ciała, aby ocenić to ćwiczenie.',
  "Log the anchor lift to score this one.": "Zapisz wynik w ćwiczeniu odniesienia, żeby ocenić to ćwiczenie.",
  'Not scored': 'Bez oceny',
  'The server cannot be reached': 'Serwer jest nieosiągalny',
  'Your server can’t be reached. Your changes are saved on this device and sync once it answers again.': 'Twój serwer jest nieosiągalny. Zmiany są zapisane na tym urządzeniu i zsynchronizują się, gdy znów odpowie.',
  "Your server can’t be reached. Showing the last copy synced with it.": "Twój serwer jest nieosiągalny. Widzisz ostatnią kopię z nim zsynchronizowaną.",
  'Server address unknown': 'Nieznany adres serwera',
  "Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Sparuj ponownie albo najpierw wyeksportuj kopię zapasową. Jeśli mimo to przejdziesz dalej, kopia tych zmian zostanie na tym urządzeniu, dopóki znów nie połączy się z tym serwerem na tym koncie. Wtedy zostaną dodane z powrotem.",
  "Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Zaloguj się ponownie albo najpierw wyeksportuj kopię zapasową. Jeśli mimo to przejdziesz dalej, kopia tych zmian zostanie na tym urządzeniu, dopóki znów nie połączy się z tym serwerem na tym koncie. Wtedy zostaną dodane z powrotem.",
  '{0} set · {1} work': '{0} seria · robocze: {1}',
  'Every exercise in this workout': 'Wszystkie ćwiczenia w tym treningu',
  'No sets are left in this workout, so there is nothing to save. Delete it from your history?': 'W tym treningu nie została żadna seria, więc nie ma czego zapisać. Usunąć go z historii?',
  // --- a custom exercise's own photo, GIF or video, and its link ---
  'Photo, GIF or video': 'Zdjęcie, GIF lub wideo',
  "Optional. A picture makes it easier to spot in a list.": "Opcjonalnie. Ze zdjęciem łatwiej je znaleźć na liście.",
  'Add': 'Dodaj',
  'Change': 'Zmień',
  'Video or guide link (optional)': 'Link do filmu lub poradnika (opcjonalnie)',
  'That link is not a web address': 'Ten link nie jest adresem strony',
  'Watch video': 'Obejrzyj film',
  'Open link': 'Otwórz link',
  "Plays from YouTube, and only once you tap": "Odtwarza się z YouTube, dopiero gdy dotkniesz",
  'Opens in YouTube': 'Otwiera się w YouTube',
  'That file type isn’t supported. Use a photo, a GIF, or an MP4, MOV or WebM video.': 'Ten typ pliku nie jest obsługiwany. Użyj zdjęcia, GIF-a albo filmu MP4, MOV lub WebM.',
  'That file is too big. Max {0} MB.': 'Ten plik jest za duży. Maksymalnie {0} MB.',
  "That video is too long. Max {0} seconds.": "Ten film jest za długi. Maksymalnie {0} s.",
  'That photo is too large to process on this device.': 'To zdjęcie jest za duże, by przetworzyć je na tym urządzeniu.',
  'You’re offline. Try again once you’re back online.': 'Jesteś offline. Spróbuj ponownie, gdy wróci internet.',
  'This browser cannot read that file.': 'Ta przeglądarka nie może odczytać tego pliku.',
  'There is no room left on this device for that file.': 'Na tym urządzeniu nie ma już miejsca na ten plik.',
  'This video may not play on every device. MP4 (H.264) plays everywhere.': 'Ten film może nie działać na każdym urządzeniu. MP4 (H.264) działa wszędzie.',
  "Your photo and video space on the server is full ({0} of {1} MB).": "Zabrakło miejsca na zdjęcia i filmy na serwerze ({0} z {1} MB).",
  'The server refused the file as too large.': 'Serwer odrzucił plik jako zbyt duży.',
  'Kept on this device only. Export with photos & videos keeps a copy.': 'Zapisane tylko na tym urządzeniu. Eksport ze zdjęciami i filmami zachowuje kopię.',
  'Your server does not store photos and videos yet.': 'Twój serwer nie przechowuje jeszcze zdjęć i filmów.',
  'This browser cannot store photos or videos here.': 'Ta przeglądarka nie może tu przechowywać zdjęć ani filmów.',
  'Photos & videos': 'Zdjęcia i filmy',
  "{0} of {1} MB used on your server": "Zajęte na twoim serwerze: {0} z {1} MB",
  '{0} waiting to upload': 'Czeka na wysłanie: {0}',
  'Export with photos & videos (.zip)': 'Eksportuj ze zdjęciami i filmami (.zip)',
  '{0} files could not be included': { one: 'Nie udało się dołączyć {0} pliku', few: 'Nie udało się dołączyć plików: {0}', many: 'Nie udało się dołączyć plików: {0}' },
  '{0} file could not be included': 'Nie udało się dołączyć {0} pliku',
  'Without photos and videos': 'Bez zdjęć i filmów',
