  "name + body part, and a photo or video if you like": "nazwa + część ciała, a do tego zdjęcie lub film, jeśli chcesz",
  "{0} photos or videos have not reached your server yet.": { one: "{0} zdjęcie lub film nie dotarło jeszcze na twój serwer.", few: "{0} zdjęcia lub filmy nie dotarły jeszcze na twój serwer.", many: "{0} zdjęć lub filmów nie dotarło jeszcze na twój serwer.", other: "{0} zdjęcia lub filmu nie dotarło jeszcze na twój serwer." },
  "{0} photo or video has not reached your server yet.": "{0} zdjęcie lub film nie dotarło jeszcze na twój serwer.",
  // --- a logged workout's own photos and videos ---
  'Add photo or video': 'Dodaj zdjęcie lub film',
  'Up to {0} photos or videos per workout.': 'Maksymalnie {0} zdjęć lub filmów na trening.',
  'A progress photo or a form-check video, kept with this workout.': 'Zdjęcie postępów albo film do sprawdzenia techniki, zapisane przy tym treningu.',
