  'Add to the rotation': 'Dodaj do rotacji',
  "No rotation yet. Add routines in the order you want to train them. The first one you haven’t logged stays up next.": "Nie masz jeszcze rotacji. Dodaj plany w kolejności, w jakiej chcesz je robić. Pierwszy niezapisany jeszcze plan jest następny w kolejce.",
  'Use this rotation': 'Użyj tej rotacji',
  'Use this rotation?': 'Użyć tej rotacji?',
  'Your own loop gets replaced.': 'Twoja własna pętla zostanie zastąpiona.',
  "Your coach gives up control of this week: Habcore Gym owns the queue from here on and repeats these sessions by itself once they are all done. A new week from the coach’s app would replace this rotation.": "Twój trener oddaje kontrolę nad tym tygodniem: od teraz kolejką zarządza Habcore Gym i sam powtarza te treningi, gdy wszystkie zostaną zrobione. Nowy tydzień z aplikacji trenera zastąpi tę rotację.",
  "Start new pass": "Zacznij nową rundę",
  'This rotation couldn’t be read. Another device may have written it.': 'Nie udało się odczytać tej rotacji. Mogło ją zapisać inne urządzenie.',
  'Discard it': 'Odrzuć ją',
