  '{0} set becomes {1}: one on each side, {2}s held every time.': '{0} seria zmienia się w {1}: po jednej na każdą stronę, za każdym razem {2} s utrzymania.',
  '{0} sets become {1}: one on each side, {2}s held every time.': { one: '{0} seria zmienia się w {1}: po jednej na każdą stronę, za każdym razem {2} s utrzymania.', few: '{0} serie zmieniają się w {1}: po jednej na każdą stronę, za każdym razem {2} s utrzymania.', many: '{0} serii zmienia się w {1}: po jednej na każdą stronę, za każdym razem {2} s utrzymania.' },
  "For side planks, single-arm holds and the like. Trains each side on its own.": "Do deski bocznej, utrzymań jednorącz i podobnych ćwiczeń. Każda strona pracuje osobno.",
  'Compare photos': 'Porównaj zdjęcia',
