  '{0} photo': '{0} zdjęcie',
  '{0} photos': { one: '{0} zdjęcie', few: '{0} zdjęcia', many: '{0} zdjęć' },
  "Your server was reached, but it refused the app’s request (CORS). If a reverse proxy such as Traefik adds CORS headers, let requests from {0} through to Habcore Gym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Udało się połączyć z serwerem, ale odrzucił on żądanie aplikacji (CORS). Jeśli reverse proxy, np. Traefik, dodaje nagłówki CORS, przepuść żądania z {0} do Habcore Gym bez zmian. Zobacz „Phone app and CORS” w docs/SELF_HOSTING.md.",
  "Could not reach {0}. Check the address and that this phone can reach it.": "Nie udało się połączyć z {0}. Sprawdź adres i to, czy ten telefon ma do niego dostęp.",
  "The end of a rest or a hold buzzes like an alarm, even in silent mode.": "Na koniec przerwy lub utrzymania telefon wibruje jak budzik, nawet w trybie cichym.",
  // --- repeat a saved workout today (#58) ---
  'Repeat today': 'Powtórz dziś',
