  '{0} exercise no longer exists and was left out.': '{0} ćwiczenie już nie istnieje i zostało pominięte.',
  '{0} exercises no longer exist and were left out.': { one: '{0} ćwiczenie już nie istnieje i zostało pominięte.', few: '{0} ćwiczenia już nie istnieją i zostały pominięte.', many: '{0} ćwiczeń już nie istnieje i zostało pominiętych.' },
  // --- show connection status, and the dot when it is off (#369, #330) ---
  'Show connection status': 'Pokazuj stan połączenia',
  'Off: the bar at the top is hidden. A dot on Home still warns when syncing is stuck.': 'Wyłączone: pasek u góry jest ukryty. Kropka na ekranie Start nadal ostrzega, gdy synchronizacja utknie.',
  'Connection problem': 'Problem z połączeniem',
  // --- auto-backup into a folder chosen on Android (#161) ---
  'Backup folder': 'Folder kopii zapasowych',
  'Chosen folder': 'Wybrany folder',
  'Use default folder': 'Użyj domyślnego folderu',
  'This folder can’t be used for backups.': 'Tego folderu nie można użyć do kopii zapasowych.',
  'Habcore Gym can no longer write to “{0}”, so copies go to Documents/Habcore Gym again. Choose the folder again to switch back.': 'Habcore Gym nie może już zapisywać w „{0}”, więc kopie znów trafiają do Documents/Habcore Gym. Wybierz folder ponownie, aby do niego wrócić.',
  'Habcore Gym can no longer write to the chosen folder, so copies go to Documents/Habcore Gym again. Choose the folder again to switch back.': 'Habcore Gym nie może już zapisywać w wybranym folderze, więc kopie znów trafiają do Documents/Habcore Gym. Wybierz folder ponownie, aby do niego wrócić.',
  // --- missed-workout nudge (lib/nudge.js; the push copy is mirrored in api/nudge-copy.js) ---
  'Nudge me when I skip a planned workout': 'Szturchnij mnie, gdy opuszczę zaplanowany trening',
  'Nudge tone': 'Ton szturchnięcia',
  'Friendly': 'Przyjazny',
  'Guilt trip': 'Wyrzuty sumienia',
  "Drill sergeant": "Surowy sierżant",
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'Jedno szturchnięcie wieczorem w zaplanowany dzień bez zapisanego treningu, między 20:00 a 21:30. Po 3 opuszczonych dniach z rzędu milknie aż do twojego następnego treningu.',
  "Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.": "Trening zapisany na innym urządzeniu? Zanim wyśle szturchnięcie, telefon sprawdza twój serwer – o ile pozwala aplikacji działać w tle. Po otwarciu aplikacji wszystko zawsze się aktualizuje.",
  'Everything okay?': 'Wszystko w porządku?',
  '{0} is still waiting. What’s up?': 'Trening „{0}” wciąż czeka. Co się dzieje?',
  "No {0} today? Even a short session tomorrow counts.": "Dziś bez treningu „{0}”? Jutro nawet krótki trening się liczy.",
  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'Ciężki dzień? Trening „{0}” poczeka. Jutro nowy start.',
  'Hey, {0} didn’t happen today. All good?': 'Hej, trening „{0}” dziś nie wyszedł. Wszystko dobrze?',
  'I miss you': 'Tęsknię za tobą',
  "{0} waited by the door all evening. For you.": "Trening „{0}” cały wieczór czekał przy drzwiach. Na ciebie.",
  'The barbell asked about you today. I didn’t know what to say.': 'Sztanga pytała dziś o ciebie. Nie wiedziałem, co powiedzieć.',
  "Was it something I said? {0} misses you.": "Czy to przez coś, co powiedziałem? Trening „{0}” za tobą tęskni.",
  'I saved you a spot on the bench. It’s still empty.': 'Zająłem ci miejsce na ławce. Wciąż jest puste.',
  'Attention, recruit!': 'Baczność, rekrucie!',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': 'Twoje postępy pakują walizki. Jutro „{0}”, bez wymówek!',
  '{0} doesn’t do itself, recruit. Move it!': 'Trening „{0}” sam się nie zrobi, rekrucie. Ruszaj się!',
  'Excuses don’t lift weights. Report for {0} tomorrow!': 'Wymówki nie podnoszą ciężarów. Jutro meldujesz się na „{0}”!',
  "Your muscles filed a missing-person report. Show up for {0}!": "Twoje mięśnie zgłosiły zaginięcie. Masz się stawić na „{0}”!",
  "That address answers, but it isn’t a Habcore Gym server. Check the URL.": "Ten adres odpowiada, ale to nie jest serwer Habcore Gym. Sprawdź adres URL.",
  "That address answers, but a login page or proxy rule replied instead of Habcore Gym. Let /api/ through to Habcore Gym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Ten adres odpowiada, ale zamiast Habcore Gym odpowiedziała strona logowania albo reguła proxy. Przepuść /api/ do Habcore Gym bez zmian. Zobacz „Phone app and CORS” w docs/SELF_HOSTING.md.",
  'Switch sides': 'Zmień stronę',
  'Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.': 'Zapisuje kopię z datą w „{0}” po każdym zakończonym treningu lub edycji planu i trzyma {1} najnowszych.',
  'Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.': 'Zapisuje kopię z datą w wybranym folderze po każdym zakończonym treningu lub edycji planu i trzyma {0} najnowszych.',
  // --- Plan: Schedule | Routines (v1.3.11) ---
  'Plan options': 'Opcje planu',
  'Your routines in a loop': 'Twoje plany w pętli',
  'Back to a fixed week?': 'Wrócić do stałego tygodnia?',
  "The loop stops. Your weekdays stay as they are, and the loop is saved for later.": "Pętla się zatrzyma. Dni tygodnia zostaną bez zmian, a pętla zostanie zapisana na później.",
  "Routines in a loop. Whatever is next stays next until you train it, whatever the day.": "Plany w pętli. Następny plan czeka, dopóki go nie zrobisz – niezależnie od dnia.",
  'The same routines on the same weekdays, every week.': 'Te same plany w te same dni, co tydzień.',
  'How you train': 'Jak trenujesz',
  "Want two routines on one day? Tap the day and pick both.": "Chcesz dwa plany jednego dnia? Dotknij dnia i wybierz oba.",
  'The loop': 'Pętla',
  "{0} of {1} done this round.": "Zrobione w tej rundzie: {0} z {1}.",
  "Drag to reorder. Tap the minus to take one out.": "Przeciągnij, żeby zmienić kolejność. Dotknij minusa, żeby usunąć plan.",
  'Trained out of order? Just pick another routine on Home.': 'Trenujesz nie po kolei? Po prostu wybierz inny plan na ekranie Start.',
  'Start the loop over': 'Zacznij pętlę od nowa',
  'Start the loop': 'Rozpocznij pętlę',
  'Also on fixed days': 'Także w stałe dni',
