  'Scroll to 0:00 to turn the rest timer off.': 'Przewiń do 0:00, aby wyłączyć minutnik.',
  "The short break between the bursts of a rest-pause set.": "Krótka przerwa między częściami serii rest-pause.",
  'Each exercise can have its own rest too. Set it in the exercise settings of a routine.': 'Każde ćwiczenie może mieć też własną przerwę. Ustawisz ją w ustawieniach ćwiczenia w planie treningowym.',
  "iPhone doesn’t let Habcore Gym vibrate. A sound or a flash does the job.": "iPhone nie pozwala Habcore Gym na wibracje. Wystarczy dźwięk albo mignięcie.",
  "No account, no cloud. Back it up anytime in Data & backup.": "Bez konta, bez chmury. Kopię zapasową zrobisz w każdej chwili w sekcji „Dane i kopie”.",
  "Effort per set is off. Turn it on in Settings → Workout to keep rating.": "Wysiłek na serię jest wyłączony. Włącz go w Ustawieniach → Trening, żeby dalej oceniać.",
  "Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.": "Wpisz kod, który twoje drugie urządzenie pokazuje w Ustawieniach → Konto → Dodaj kolejne urządzenie. To urządzenie dostanie wtedy własny klucz dostępu.",
  'Open Settings → Account → “Pair the mobile app” on the Habcore Gym site you’re already signed into, then enter its address and the code shown there.': 'Na stronie Habcore Gym, na której już się zalogowano, otwórz Ustawienia → Konto → „Sparuj aplikację mobilną”, a potem wpisz tutaj jej adres i wyświetlony tam kod.',
  'Open Settings → Account → “Pair the mobile app” on your Habcore Gym site in a browser and enter the new code shown there. What this phone kept is merged into your account.': 'Otwórz Ustawienia → Konto → „Sparuj aplikację mobilną” na swojej stronie Habcore Gym w przeglądarce i wpisz nowy kod, który się tam pojawi. To, co zachował ten telefon, zostanie scalone z twoim kontem.',
  'Change the time left': 'Zmień pozostały czas',
  'Paused': 'Wstrzymano',
