  "That file isn’t a Habcore Gym backup.": "Ten plik nie jest kopią zapasową Habcore Gym.",
  "That zip was repacked. Import the original backup file.": "Ten plik zip został spakowany ponownie. Zaimportuj oryginalny plik kopii zapasowej.",
  'Couldn’t read that file.': 'Nie udało się odczytać tego pliku.',
  'This server doesn’t know that passkey. Make a profile first.': 'Ten serwer nie zna tego klucza dostępu. Najpierw utwórz profil.',
  'That took a little too long. Give it another go.': 'Trwało to trochę za długo. Spróbuj jeszcze raz.',
  "This server only takes changes made at {0}. If you opened Habcore Gym at another address, whoever runs the server can set ORIGIN and RP_ID to match it (the self-hosting guide shows how).": "Ten serwer przyjmuje zmiany tylko z adresu {0}. Jeśli otwierasz Habcore Gym pod innym adresem, administrator serwera może ustawić ORIGIN i RP_ID na ten adres (jak to zrobić – w przewodniku self-hostingu).",
  "That code didn’t work. Codes last 5 minutes and work once, so grab a fresh one.": "Ten kod nie zadziałał. Kod jest ważny 5 minut i działa tylko raz – wygeneruj nowy.",
