  "Plain http:// isn’t encrypted. Fine on your home network, but use https:// if your server is reachable from the internet.": "Zwykłe http:// nie jest szyfrowane. W sieci domowej to nie problem, ale jeśli twój serwer jest dostępny z internetu, użyj https://.",
  "Could not reach {0} over https://. If your server runs on plain http (common at home), type http://{0} instead.": "Nie udało się połączyć z {0} przez https://. Jeśli twój serwer działa na zwykłym http (typowe w domu), wpisz http://{0}.",
