  "Each set one step lighter than the one before. The weight above is the first set.": "Każda seria o jeden krok lżejsza od poprzedniej. Obciążenie powyżej dotyczy pierwszej serii.",
  "Sets open at {0}. The first set goes up when every set reaches its reps, and the rest follow it.": "Serie zaczynają się od {0}. Pierwsza seria idzie w górę, gdy w każdej serii zrobisz zaplanowane powtórzenia, a pozostałe idą za nią.",
  "The first set goes up when every set reaches its reps, and the rest follow it.": "Pierwsza seria idzie w górę, gdy w każdej serii zrobisz zaplanowane powtórzenia, a pozostałe idą za nią.",
  "All sets at the same weight.": "Wszystkie serie z tym samym obciążeniem.",

  // v1.4.0 additions
  'Cloudflare Access': 'Cloudflare Access',
