  "Only if your server is behind Cloudflare Access: the service token this phone sends with every request to it. Kept in this phone’s secure storage.": "Tylko jeśli twój serwer działa za Cloudflare Access: token usługi, który ten telefon wysyła z każdym żądaniem do serwera. Przechowywany w bezpiecznej pamięci telefonu.",
