  'As entered': 'Jak wpisano',
  'Each': 'Na sztukę',
  'Both': 'Razem',
  "Weight means": "Obciążenie oznacza",
  "The weight of the one you hold. One arm, so it counts once.": "Ciężar hantla, który trzymasz. Jedna ręka, więc liczy się raz.",
  "The weight of one, so 20 means 20 in each hand. Volume counts both.": "Ciężar jednego hantla: 20 to 20 w każdej ręce. Objętość liczy oba.",
  "Both together, so 40 means two 20s.": "Oba razem: 40 to dwa po 20.",
  "Counted as you type it, the way it always was.": "Liczone tak, jak wpisujesz – jak dotąd.",
  // --- dumbbell inventory (#376) ---
  "You’ve outgrown the rack: {0} {1} is your heaviest dumbbell, so the weight stays.": "Brakuje ci już cięższych hantli: {0} {1} to twój najcięższy, więc obciążenie zostaje.",
  'Dumbbells': 'Hantle',
  "The weights you own, one bell each. Progression, deloads, warm-ups and the + and − buttons of dumbbell lifts land only on these.": "Hantle, które masz – każdy ciężar osobno. Progresja, deloady, rozgrzewka i przyciski + i − w ćwiczeniach z hantlami wybierają tylko spośród nich.",
  "No list yet, so dumbbell lifts step by their increment as usual.": "Nie ma jeszcze listy, więc ćwiczenia z hantlami rosną jak zwykle o swój krok.",
  'Fill in {0} to {1} {2}, every {3}': 'Wpisz od {0} do {1} {2}, co {3}',
  'Clear the list': 'Wyczyść listę',
  "Any weight. Tap to list the ones you own.": "Dowolne obciążenie. Dotknij, aby wpisać hantle, które masz.",
  // --- sets to failure (v1.4.0) ---
  'F': 'F',
  'Taken to failure': 'Do upadku',
  "Nothing left in the tank": "Nic już nie zostało w baku",
  'Last set to failure': 'Ostatnia seria do upadku',
  "The last set goes until nothing is left, and counts as all-out effort unless you rate it.": "Ostatnią serię robisz do oporu i liczy się jako maksymalny wysiłek, chyba że sam ją ocenisz.",
  "Plan the final set as an all-out one.": "Zaplanuj ostatnią serię do oporu.",
  // --- triple progression (issue #179) ---
  'Triple progression': 'Potrójna progresja',
  "Reps climb to the top of the range, then a set is added, up to your most sets. All of them at the top and the weight goes up, back to your first sets and reps.": "Powtórzenia rosną do górnej granicy zakresu, potem dochodzi seria – aż do maksymalnej liczby serii. Gdy wszystkie są na górnej granicy, obciążenie idzie w górę, a serie i powtórzenia wracają do początku.",
  "Same weight, aim for {0} reps in every set.": { one: "To samo obciążenie, celuj w {0} powtórzenie w każdej serii.", few: "To samo obciążenie, celuj w {0} powtórzenia w każdej serii.", many: "To samo obciążenie, celuj w {0} powtórzeń w każdej serii.", other: "To samo obciążenie, celuj w {0} powtórzenia w każdej serii." },
  "Same weight, aim for {0} reps on the last set.": { one: "To samo obciążenie, celuj w {0} powtórzenie w ostatniej serii.", few: "To samo obciążenie, celuj w {0} powtórzenia w ostatniej serii.", many: "To samo obciążenie, celuj w {0} powtórzeń w ostatniej serii.", other: "To samo obciążenie, celuj w {0} powtórzenia w ostatniej serii." },
  "{0} reps in every set! Add a set at {1} reps.": { one: "{0} powtórzenie w każdej serii! Dodaj serię z powtórzeniami: {1}.", few: "{0} powtórzenia w każdej serii! Dodaj serię z powtórzeniami: {1}.", many: "{0} powtórzeń w każdej serii! Dodaj serię z powtórzeniami: {1}.", other: "{0} powtórzenia w każdej serii! Dodaj serię z powtórzeniami: {1}." },
  "Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.": "Górna granica we wszystkich seriach ({0}). {1} {2} więcej, z powrotem do {3} × {4}.",
  "Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.": "Górna granica we wszystkich seriach ({0}). {1} {2} mniej pomocy, z powrotem do {3} × {4}.",
  "Short of the target, but more reps than before. Same sets and reps again.": "Trochę zabrakło do celu, ale zrobiłeś więcej powtórzeń niż wcześniej. Powtórz te same serie i powtórzenia.",
  "Missed reps last time. Same sets and reps again ({0} of {1} to go).": "Ostatnio zabrakło powtórzeń. Powtórz te same serie i powtórzenia (zostało {0} z {1}).",
  "Stuck for {0} sessions. Deload to {1} {2} and start again at {3} sets of {4}.": "Zastój od kilku treningów ({0}). Deload do {1} {2} i start od nowa: {3} × {4}.",
  "Stuck for {0} sessions. Back to {1} {2} of help, start again at {3} sets of {4}.": "Zastój od kilku treningów ({0}). Wracasz do {1} {2} pomocy i zaczynasz od nowa: {3} × {4}.",
  'Sets from': 'Serie od',
  'Sets up to': 'Serie do',
