  "Exercise chips at the top": "Kropki ćwiczeń u góry",
  "A numbered dot per exercise, filled as you go. Tap one to jump there.": "Ponumerowana kropka dla każdego ćwiczenia, wypełnia się w trakcie. Dotknij kropki, aby przejść do ćwiczenia.",
