  'Note removed': 'Notatka usunięta',
  'Remove note': 'Usuń notatkę',
  "Life happens. Leave yourself a note, and the missed-day nudge lets this one go.": "Różnie bywa. Zostaw sobie notatkę, a przypomnienie o opuszczonym treningu odpuści ten dzień.",
  'Anything else? (optional)': 'Coś jeszcze? (opcjonalnie)',
