  'Soft': 'Delikatny',
  'Tap one to hear it.': 'Dotknij, aby posłuchać.',
  "Ding-dong. Rest is over, class is in.": "Ding-dong. Koniec przerwy, wracamy do ćwiczeń.",
  "Your sports watch, calling you back.": "Jak zegarek sportowy, który woła cię z powrotem.",
  "Coach wants you back on the bar.": "Trener woła cię z powrotem do sztangi.",
  "Gentle, for headphones or a quiet room.": "Delikatny, do słuchawek albo cichego pomieszczenia.",
  // --- Coach: AI data sharing ---
  'AI data sharing': 'Udostępnianie danych AI',
  'Allow': 'Zezwól',
  "Allowed {0}": "Zgoda od {0}",
  'Anything you type to the Coach': 'Wszystko, co piszesz do Trenera',
  "Change your mind anytime under AI data sharing in the Coach menu.": "Zdanie zmienisz w każdej chwili w menu Trenera, w sekcji „Udostępnianie danych AI”.",
  "Nothing allowed yet": "Nie ma jeszcze żadnych zgód",
  "Okay, nothing was sent.": "Dobrze, nic nie zostało wysłane.",
  "Send your training to {0}?": "Wysłać dane o twoich treningach do {0}?",
  "The Coach asks before anything leaves.": "Trener zawsze pyta, zanim cokolwiek wyśle.",
  'Through your server': 'Przez twój serwer',
  "To answer, the Coach sends this through your Habcore Gym server to {0}, an AI service outside Habcore Gym that your server’s admin picked:": "Żeby odpowiedzieć, Trener wysyła przez twój serwer Habcore Gym do {0} – zewnętrznej usługi AI wybranej przez administratora serwera – te dane:",
  "To answer, this device sends this straight to {0}, an AI service outside Habcore Gym, with your API key:": "Żeby odpowiedzieć, to urządzenie wysyła bezpośrednio do {0} – zewnętrznej usługi AI – z twoim kluczem API te dane:",
  "Who may see your training": "Kto może widzieć twoje treningi",
  "Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.": "Komu Trener może wysyłać dane o twoich treningach z tego urządzenia. Gdy cofniesz zgodę, Trener zapyta ponownie następnym razem. Model w twojej własnej sieci nie wymaga zgody.",
  'With your API key': 'Z twoim kluczem API',
  'Withdraw': 'Cofnij zgodę',
  "Withdrawn. The Coach will ask before it sends anything again.": "Zgoda cofnięta. Trener zapyta, zanim znów coś wyśle.",
  'Your answers to the Coach: goal, days, equipment, limits and injuries': 'Twoje odpowiedzi dla Trenera: cel, dni, sprzęt, ograniczenia i kontuzje',
  "Your body weight and goal weight": "Twoja masa ciała i docelowa waga",
  'Your data, your call': 'Twoje dane, twoja decyzja',
  "Your name, email and sign-in stay put. {0} handles the rest under its own privacy terms.": "Imię, e-mail i dane logowania nie są wysyłane. Resztę {0} przetwarza według własnych zasad prywatności.",
  "Your plan: routines, exercises, sets, reps and schedule": "Twój plan: plany treningowe, ćwiczenia, serie, powtórzenia i harmonogram",
  'Your unit and language': 'Twoja jednostka i język',
  "Your workouts: weights, reps, times, effort and session notes": "Twoje treningi: obciążenia, powtórzenia, czasy, wysiłek i notatki z treningów",
  // --- delete my account (App Store rule 5.1.1(v)) ---
  'Delete my account': 'Usuń moje konto',
  "Removes your profile and everything in it from this server.": "Usuwa twój profil i wszystko, co w nim jest, z tego serwera.",
  'Delete your account?': 'Usunąć konto?',
  "Your profile, workouts, body weight, photos and videos are deleted from this server for good. There is no undo, and not even your admin can bring them back.": "Twój profil, treningi, ważenia, zdjęcia i filmy zostaną trwale usunięte z tego serwera. Nie da się tego cofnąć – nawet administrator ich nie odzyska.",
  "Want a copy first? Export a backup. You can import it into Habcore Gym anytime.": "Chcesz najpierw zrobić kopię? Wyeksportuj kopię zapasową – możesz ją w każdej chwili zaimportować do Habcore Gym.",
  'Type {0} to confirm.': 'Wpisz {0}, aby potwierdzić.',
  'Account name': 'Nazwa konta',
  'Delete forever': 'Usuń na zawsze',
  "That is not your account name.": "To nie jest nazwa twojego konta.",
  'You’re the only admin here, and other profiles still use this server. Make someone else an admin first.': 'Jesteś tu jedynym administratorem, a inne profile wciąż korzystają z tego serwera. Najpierw zrób administratorem kogoś innego.',
  'Couldn’t delete the account. Nothing was removed.': 'Nie udało się usunąć konta. Nic nie zostało usunięte.',
  'Your account is gone. Thanks for every rep.': 'Twojego konta już nie ma. Dzięki za każde powtórzenie.',
  "Confirm it’s you to delete your Habcore Gym account": "Potwierdź, że to ty, aby usunąć konto Habcore Gym",
  'Not confirmed on this phone. Nothing was deleted.': 'Nie potwierdzono na tym telefonie. Nic nie zostało usunięte.',
  "This phone has no screen lock, so the name you typed is the only check.": "Ten telefon nie ma blokady ekranu, więc jedynym zabezpieczeniem jest wpisana nazwa.",
  "Your phone checks that it’s you (face, fingerprint or passcode), then the account is deleted.": "Telefon sprawdzi, czy to ty (twarz, odcisk palca lub kod), a potem usunie konto.",
  // --- first-start permission steps ---
  'Never miss the end of a rest': 'Nigdy nie przegap końca przerwy',
  "One quick thing": "Jeszcze jedna sprawa",
  "Rest timer, right on the lock screen": "Minutnik przerwy na ekranie blokady",
  "Training reminders, only if you switch them on": "Przypomnienia o treningu – tylko jeśli je włączysz",
  'You can change it anytime in your phone’s settings.': 'Możesz to zmienić w każdej chwili w ustawieniach telefonu.',
  "Habcore Gym can tap you on the shoulder when a rest is over, even with the phone locked in your pocket.": "Habcore Gym da ci znać, gdy przerwa się skończy – nawet gdy zablokowany telefon leży w kieszeni.",
  // --- animation quality (store apps) ---
  'A good size for this screen.': 'Dobry rozmiar dla tego ekranu.',
