  "Download failed. Tap to try again.": "Nie udało się pobrać. Dotknij, aby spróbować ponownie.",
  'Download over Wi-Fi only': 'Pobieraj tylko przez Wi-Fi',
  'Downloaded · {0}': 'Pobrane · {0}',
  'Downloading… {0}%': 'Pobieranie… {0}%',
  "No animation, just the picture. Easy on battery.": "Bez animacji, tylko obrazek. Oszczędza baterię.",
  "Not downloaded": "Niepobrane",
  'On this device': 'Na tym urządzeniu',
  'Sharper animations aren’t available on this device yet. The built-in ones work everywhere.': 'Ostrzejsze animacje nie są jeszcze dostępne na tym urządzeniu. Wbudowane działają wszędzie.',
  "Sharper animations come only through the app stores. This APK keeps the ones built into it.": "Ostrzejsze animacje są dostępne tylko w wersji ze sklepów z aplikacjami. Ten APK korzysta z wbudowanych.",
  "Sharper animations download once per figure. Until they’re here you see the built-in ones, so nothing ever goes blank.": "Ostrzejsze animacje pobierają się raz dla każdej sylwetki. Do tego czasu widzisz wbudowane, więc nic nie znika.",
