  'Pick a time': 'Wybierz czas',
  'Rest between sides': 'Przerwa między stronami',
  'Rest between warm-ups': 'Przerwa między seriami rozgrzewkowymi',
  "Warm-ups are light, so they can rest less, or not at all. The last one still gets the full rest before your first work set.": "Serie rozgrzewkowe są lekkie, więc przerwa może być krótsza albo żadna. Po ostatniej i tak masz pełną przerwę przed pierwszą serią roboczą.",
  // --- progress photos for any day (#557) ---
  'Add photos': 'Dodaj zdjęcia',
  'Each photo goes on the day it was taken.': 'Każde zdjęcie trafia na dzień, w którym zostało zrobione.',
  "No progress photos yet. Add one for today or any day before.": "Nie masz jeszcze zdjęć postępów. Dodaj zdjęcie z dziś albo z wcześniejszego dnia.",
  "The photo says it was taken on {0}. Change the day if it was another one.": "Według danych zdjęcia zrobiono je {0}. Zmień dzień, jeśli to był inny.",
  'They all go on the day below.': 'Wszystkie trafią na dzień poniżej.',
  'Which day is this photo from?': 'Z którego dnia jest to zdjęcie?',
  "Your server keeps photos only on days with a workout. An update lets it keep them for any day.": "Twój serwer przechowuje zdjęcia tylko w dni z treningiem. Po aktualizacji będzie je przechowywać dla każdego dnia.",
  'Add {0} photo': 'Dodaj {0} zdjęcie',
  "Add {0} photos": { one: "Dodaj {0} zdjęcie", few: "Dodaj {0} zdjęcia", many: "Dodaj {0} zdjęć", other: "Dodaj {0} zdjęcia" },
