  "{0} photos know their day and go there. The others go on the day below.": { one: "{0} zdjęcie ma zapisaną datę i tam trafi. Pozostałe trafią na dzień poniżej.", few: "{0} zdjęcia mają zapisaną datę i tam trafią. Pozostałe trafią na dzień poniżej.", many: "{0} zdjęć ma zapisaną datę i tam trafi. Pozostałe trafią na dzień poniżej.", other: "{0} zdjęcia ma zapisaną datę i tam trafi. Pozostałe trafią na dzień poniżej." },
