  "This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.": "Ta aplikacja nie może potwierdzić kluczem dostępu. Wygeneruj kod w przeglądarce zalogowanej na ten profil albo najpierw ustaw tam hasło.",
