  'Apple Watch': 'Apple Watch',
  "Weight": "Obciążenie",
  'Send workouts to the watch': 'Wysyłaj treningi na zegarek',
  'Open on the watch': 'Otwórz na zegarku',
  "Start a workout on the phone and Habcore Gym pops up on your wrist.": "Zacznij trening w telefonie, a Habcore Gym od razu pojawi się na zegarku.",
  'Not allowed': 'Brak zgody',
  'Turn on Apple Health and the watch measures your heart rate for every set.': 'Włącz Apple Zdrowie, a zegarek zmierzy tętno w każdej serii.',
  "Tap the wrist when a rest is over": "Wibracja na nadgarstku po przerwie",
  "No Apple Watch paired with this iPhone": "Z tym iPhone’em nie jest sparowany żaden Apple Watch",
