  "Habcore Gym is on your Apple Watch": "Habcore Gym jest na twoim Apple Watch",
  'Last heard from the watch: {0}': 'Ostatni kontakt z zegarkiem: {0}',
  "The watch hasn’t checked in yet. Open Habcore Gym on it once.": "Zegarek jeszcze się nie odezwał. Otwórz na nim raz Habcore Gym.",
  "Not allowed on the watch. Allow it in the Health app on your iPhone.": "Brak zgody na zegarku. Zezwól na dostęp w aplikacji Zdrowie na iPhonie.",
  "Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.": "Tętno w trakcie treningu i przy każdej serii, a trening zapisany w aplikacji Zdrowie. Zegarek zapyta o zgodę tylko raz.",
  'Apple Health': 'Apple Zdrowie',
  'Write to Apple Health': 'Zapisuj w Apple Zdrowie',
  'Open Apple Health': 'Otwórz Apple Zdrowie',
  "Workouts and weigh-ins go to Apple Health when you finish or change them.": "Treningi i ważenia trafiają do Apple Zdrowie, gdy je kończysz lub zmieniasz.",
  "Writing to Apple Health": "Zapisywanie w Apple Zdrowie włączone",
  'Apple Health permission not granted': 'Nie przyznano uprawnienia Apple Zdrowie',
  'Could not write to Apple Health': 'Nie udało się zapisać w Apple Zdrowie',
  'Could not remove it from Apple Health': 'Nie udało się usunąć z Apple Zdrowie',
  'Stop writing to Apple Health?': 'Przestać zapisywać w Apple Zdrowie?',
  "What Habcore Gym already wrote can stay in Apple Health as your data, or be removed from it.": "To, co Habcore Gym już zapisał, może zostać w Apple Zdrowie jako twoje dane albo zostać stamtąd usunięte.",
  'Your workouts in Apple Health': 'Twoje treningi w Apple Zdrowie',
  "Habcore Gym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.": "Habcore Gym może zapisywać każdy trening i każde ważenie w Apple Zdrowie, a twój Apple Watch pokaże tętno podczas ćwiczeń.",
  "Workouts and weigh-ins saved to Apple Health": "Treningi i ważenia zapisane w Apple Zdrowie",
  'Heart rate per set on your Apple Watch': 'Tętno w każdej serii na Apple Watch',
  "AirPods Pro 3 or Powerbeats Pro 2 in? Your iPhone measures the heart rate for every set, unless your Apple Watch is already on it.": "Masz w uszach AirPods Pro 3 albo Powerbeats Pro 2? iPhone zmierzy tętno w każdej serii, chyba że już robi to Apple Watch.",
  'Switch it off anytime in Settings': 'Wyłączysz to w każdej chwili w Ustawieniach',
  'You can change it anytime in Settings.': 'Możesz to zmienić w każdej chwili w Ustawieniach.',
