  "What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.": "Ile ważą gryfy na twojej siłowni. Każde ćwiczenie z danym gryfem liczy talerze od jego wagi, chyba że ćwiczenie ma ustawiony własny. Zapisane obciążenia to nadal sumy.",
  "Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.": "Większość ćwiczeń w bibliotece używa gryfu „{0}”, a kilka – „{1}”. Jeśli chcesz krótki gryf we wszystkich, ustaw oba.",
