  "“{0}” is done. Nicely lifted. What next?": "Program „{0}” ukończony. Świetna robota! Co dalej?",
  'Week {0} of {1}: {2}% of your best 1RM': 'Tydzień {0} z {1}: {2}% twojego najlepszego 1RM',
  'Week {0} of {1}: deload week': 'Tydzień {0} z {1}: tydzień deloadu',
  '{0} lift at a %1RM': '{0} ćwiczenie z %1RM',
  "{0} lifts at a %1RM": { one: "{0} ćwiczenie z %1RM", few: "{0} ćwiczenia z %1RM", many: "{0} ćwiczeń z %1RM", other: "{0} ćwiczenia z %1RM" },
  "Added with {0} new routine.": "Dodano razem z {0} nowym planem.",
  "Added with {0} new routines.": { one: "Dodano razem z {0} nowym planem.", few: "Dodano razem z {0} nowymi planami.", many: "Dodano razem z {0} nowymi planami.", other: "Dodano razem z {0} nowego planu." },
  '{0} week': '{0} tydzień',
