  "It starts with the plates, dumbbells and bars you have set now. Change them once it’s the active gym.": "Na start dostaje talerze, hantle i sztangi, które masz teraz ustawione. Zmienisz je, gdy stanie się aktywną siłownią.",
  "Plates, dumbbells, bars and machine stacks are kept per gym. Switch gyms and all of it switches.": "Talerze, hantle, sztangi i stosy ciężarów są zapisywane dla każdej siłowni. Zmień siłownię, a zmieni się wszystko.",
  "Active gym": "Aktywna siłownia",
  "Pick a gym": "Wybierz siłownię",
  "Equipment at {0}": "Sprzęt w {0}",
  "Train in more than one place? Add a profile for each gym and each keeps its own plates, dumbbells and bars.": "Trenujesz w kilku miejscach? Dodaj profil dla każdej siłowni, a każda będzie miała własne talerze, hantle i sztangi.",
  "Switch to {0}?": "Przełączyć na {0}?",
  "Sets you haven’t done yet move onto the plates, dumbbells and stacks there.": "Serie, które jeszcze przed tobą, dopasują się do tamtejszych talerzy, hantli i stosów.",
  "Switch": "Przełącz",
  "Gym: {0}": "Siłownia: {0}",
  "Arrive here, tap a check-in sticker or start a workout here, and Habcore Gym uses this gym’s plates, dumbbells and bars.": "Przyjdź tutaj, dotknij naklejki check-in albo zacznij tu trening, a Habcore Gym użyje talerzy, hantli i sztang tej siłowni.",
