  // --- v1.4.4: LAN http for the phone Coach (#913), freestyle progression (#910), watch idle finish (#904) ---
  "Plain http:// only works for an address on your home network, like 192.168.x.x, a .local name or a Tailscale 100.x address. Anything on the internet needs https://.": "Nieszyfrowane http:// działa tylko z adresem w twojej sieci domowej, np. 192.168.x.x, nazwą .local albo adresem Tailscale 100.x. Wszystko w internecie wymaga https://.",
  "Plain http only on your home network": "Nieszyfrowane http tylko w sieci domowej",
  "Freestyle repeats what you did last time, with no progression rule. Rules apply to exercises in a routine.": "Trening dowolny powtarza to, co było ostatnio, bez reguły progresji. Reguły działają dla ćwiczeń w planie.",
  "Your watch thought this workout was forgotten. It keeps going here.": "Zegarek uznał ten trening za zapomniany. Tutaj trwa dalej.",
  "No rule (freestyle)": "Bez reguły (dowolny)",
  "Freestyle keeps the numbers you set. A rule picked here applies to this workout only.": "Trening dowolny zostawia liczby, które ustawisz. Reguła wybrana tutaj działa tylko w tym treningu.",
  // --- v1.4.5: warm-ups that build themselves, and the Coach in the middle of a workout ---
  "A number of ramp sets": "Określona liczba serii dochodzących",
  "Add a warm-up": "Dodaj rozgrzewkę",
  "Ask the Coach": "Zapytaj Trenera",
  "Automatic warm-ups": "Automatyczna rozgrzewka",
  "Bar": "Gryf",
  "Body": "Ciało",
  "Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.": "Liczone od ciężaru roboczego i zaokrąglane do talerzy i hantli tej siłowni. W ustawieniach ćwiczenia możesz wybrać inaczej.",
  "Built from your work weight when the workout starts.": "Liczone od ciężaru roboczego na starcie treningu.",
  "Coach programme": "Program Trenera",
  "Compound lifts": "Ćwiczenia wielostawowe",
  "Default": "Domyślnie",
  "Default (auto)": "Domyślnie (auto)",
  "Default (none)": "Domyślnie (brak)",
  "Do {0} last": "Zrób {0} na koniec",
  "Do {0} next": "Zrób {0} jako następne",
  "Each one closes half the gap to the work weight.": "Każda zmniejsza o połowę różnicę do ciężaru roboczego.",
  "Every loaded lift": "Każde ćwiczenie z obciążeniem",
  "Feeling great": "Czuję moc",
  "Follows Settings → Workout → Automatic warm-ups.": "Według Ustawienia → Trening → Automatyczna rozgrzewka.",
  "For this workout": "Na ten trening",
  "Heavy lifts get more rungs, light ones one or none.": "Ciężkie ćwiczenia dostają więcej stopni, lekkie jeden albo żaden.",
  "It hurts": "Boli",
  "It hurts, it’s taken, no time, feeling great": "Boli, zajęte, brak czasu, czuję moc",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "Coś kłuje, więc do końca lżej. Przerwij, jeśli dalej boli.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "Coś kłuje, więc pozostałe serie przechodzą na ruch, który obciąża ten sam mięsień pod łagodniejszym kątem.",
  "Keep these warm-ups": "Zachowaj tę rozgrzewkę",
  "Kept. Same warm-ups next time, scaled to your work weight.": "Zapisane. Następnym razem ta sama rozgrzewka, dopasowana do ciężaru roboczego.",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Zapisane serie i twój plan zostają bez zmian. Trener nie jest lekarzem ani fizjoterapeutą. Jeśli coś boli, skonsultuj się ze specjalistą.",
  "Looking at your workout…": "Patrzę na twój trening…",
  "Machine’s taken": "Maszyna zajęta",
  "My own": "Własne",
  "New programme “{0}”": "Nowy program „{0}”",
  "Nothing at {0} {1}: that one starts cold.": "Przy {0} {1} bez rozgrzewki – start na zimno.",
  "Nothing could be applied any more.": "Nie dało się już niczego zastosować.",
  "Nothing to change. Carry on as planned.": "Nic do zmiany. Trenuj dalej zgodnie z planem.",
  "One set less keeps the session doable today and still counts.": "Jedna seria mniej – dziś dasz radę, a trening i tak się liczy.",
  "Only the warm-ups you plan yourself.": "Tylko rozgrzewka zaplanowana przez ciebie.",
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": "Stopniowana od ciężaru roboczego: więcej stopni przy dużym ciężarze, mniej przy małym.",
  "Remove warm-up {0}": "Usuń rozgrzewkę {0}",
  "Revise programme “{0}”": "Popraw program „{0}”",
  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": "Plany, ćwiczenia, serie i powtórzenia, rozgrzewki, programy, twój tygodniowy harmonogram, ustawienia progresji i to, co da się załadować na twojej siłowni.",
  "Running on empty": "Brak energii",
  "Saved in the routine, scaled to your work weight": "Zapisane w planie, dopasowane do ciężaru roboczego",
  "Saved under Plan → Programmes. It starts when you start it.": "Zapisany w Plan → Programy. Zacznie się, gdy go uruchomisz.",
  "Short on time": "Mało czasu",
  "Skip the rest of {0}": "Pomiń resztę: {0}",
  "Something else": "Coś innego",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "Przysiady, wyciskania, wiosłowania i spółka dostają serie dochodzące. Uginania i unoszenia zaczynają na zimno.",
  "Straight into the work sets.": "Od razu do serii roboczych.",
  "That workout is over, so these can’t be applied any more.": "Ten trening się skończył, więc nie da się już tego zastosować.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "Aplikacja buduje rozgrzewkę od ciężaru roboczego: więcej serii przy dużym ciężarze, mniej przy małym – z talerzy twojej siłowni.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "Stojak zajęty, więc zrób to na koniec. Reszta treningu go nie potrzebuje.",
  "There’s no workout running.": "Nie trwa żaden trening.",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "Ta rozgrzewka poprzedza serie robocze na każdym treningu jako procent ciężaru roboczego, więc rośnie razem z nim.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "To jest demo, więc nie stoi za mną model AI. Na twoim własnym serwerze analizuję trening i proponuję takie zmiany.",
  "Warm-up {0}": "Rozgrzewka {0}",
  "Warm-ups": "Rozgrzewka",
  "What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.": "Co się dzieje? Trener zaproponuje kilka zmian w tym, co zostało z treningu. Zapisane serie zostają bez zmian.",
  "Where, and what movement hurts? (optional)": "Gdzie i przy jakim ruchu boli? (opcjonalnie)",
  "With {0} {1} today: {2}": "Dziś przy {0} {1}: {2}",
  "You can keep training, the answer waits here and in the Coach.": "Możesz dalej trenować, odpowiedź poczeka tutaj i u Trenera.",
