  "Festive flame": "Świąteczny płomień",
  "Festive flame on. Your streak looks very merry.": "Świąteczny płomień włączony. Twoja Passa wygląda bardzo świątecznie.",
  "Halloween and friends, little extras for the time of year. All optional.": "Halloween i inne okazje – małe dodatki na daną porę roku. Wszystko opcjonalne.",
  "Lifted in {0} so far": "Łącznie podniesione w {0}",
  "Missed a day? Its door waits for you.": "Ominął cię dzień? Jego okienko na ciebie czeka.",
