  "Wearing it. Very merry.": "Masz go na sobie. Bardzo świątecznie.",
  "Weeks in a row with at least one workout. The elves are taking notes.": "Tygodnie z rzędu z co najmniej jednym treningiem. Elfy robią notatki.",
  "Your longest streak in {0}": "Twoja najdłuższa Passa w {0}",
  "Your most trained muscle in {0}": "Twoja najczęściej trenowana partia mięśni w {0}",
  "Your present: a festive flame": "Twój prezent: świąteczny płomień",
  "Your streak wears a Santa hat, all year if you like. Change it any time in Settings, Icons.": "Twoja Passa nosi czapkę Mikołaja – przez cały rok, jeśli chcesz. Zmienisz to w każdej chwili w Ustawienia → Ikony.",
  "{0}% of all the work you did. Clearly a favourite.": "{0}% całej twojej pracy. Ewidentny faworyt.",
