  "Chimney climb": "Wspinaczka po kominie",
  "Elf on the floor": "Elf na podłodze",
  "Last-minute dash": "Sprint na ostatnią chwilę",
  "Knees on the floor count just the same.": "Kolana na podłodze liczą się tak samo.",
  "Carry the shopping like it owes you money. Tall chest, slow steps.": "Noś zakupy, jakby były ci winne pieniądze. Klatka wysoko, wolne kroki.",
  "You found Rudolph! He says hi and hides again. New spot tomorrow.": "Rudolf się znalazł! Mówi cześć i znów się chowa. Jutro nowa kryjówka.",
  "{0} bauble on the tree, {1} lit": "{0} bombka na choince, {1} świeci",
  "{0} baubles on the tree, {1} lit": { one: "{0} bombka na choince, świecących: {1}", few: "{0} bombki na choince, świecących: {1}", many: "{0} bombek na choince, świecących: {1}", other: "{0} bombki na choince, świecących: {1}" },
  "About {0} minute, two moves back to back": "Około {0} minuty, dwa ruchy jeden po drugim",
  "About {0} minutes, two moves back to back": { one: "Około {0} minuty, dwa ruchy jeden po drugim", few: "Około {0} minut, dwa ruchy jeden po drugim", many: "Około {0} minut, dwa ruchy jeden po drugim", other: "Około {0} minuty, dwa ruchy jeden po drugim" },
  "That is about {0} reindeer. Rudolph would like a lie-down.": { one: "To mniej więcej {0} renifer. Rudolf chętnie by się położył.", few: "To mniej więcej {0} renifery. Rudolf chętnie by się położył.", many: "To mniej więcej {0} reniferów. Rudolf chętnie by się położył.", other: "To mniej więcej {0} renifera. Rudolf chętnie by się położył." },
  "Choose a photo": "Wybierz zdjęcie",
  "Drag to move, pinch or slide to zoom.": "Przeciągnij, żeby przesunąć. Rozsuń palce lub użyj suwaka, żeby przybliżyć.",
  "Frame your best side": "Pokaż swoją lepszą stronę",
  "Only you see it, and it stays on this device.": "Widzisz je tylko ty i zostaje na tym urządzeniu.",
  "Only you see it, here and on your other devices. Not even an admin can.": "Widzisz je tylko ty – tutaj i na swoich innych urządzeniach. Nawet administrator nie ma do niego dostępu.",
  "Photo crop. Arrow keys move it, plus and minus zoom.": "Kadrowanie zdjęcia. Strzałki przesuwają, plus i minus przybliżają.",
  "Picture removed. Back to the letter.": "Zdjęcie usunięte. Znowu jest inicjał.",
  "Picture set. Looking sharp.": "Zdjęcie ustawione. Wyglądasz świetnie.",
  "Profile picture": "Zdjęcie profilowe",
  "Remove picture": "Usuń zdjęcie",
  "That isn’t a photo. Try a JPEG, PNG, WebP or HEIC.": "To nie jest zdjęcie. Spróbuj JPEG, PNG, WebP lub HEIC.",
  "Use this photo": "Użyj tego zdjęcia",
  "Zoom": "Powiększenie",
  "Missed plan": "Opuszczony plan",
  "Open this day": "Otwórz ten dzień",
  "Planned, not trained. Any other day this week still counts.": "Zaplanowane, bez treningu. Każdy inny dzień tego tygodnia wciąż się liczy.",
  "Planned, not trained. Any workout that week would have counted.": "Zaplanowane, bez treningu. Każdy trening w tamtym tygodniu by się liczył.",
  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "Zaplanowane, bez treningu. Nic się nie stało: był trening innego dnia w tym tygodniu, więc i tak się liczy.",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "1 zamrożenie w zapasie, zdobywane co 4 tygodnie z treningiem. Dwa opuszczone tygodnie z rzędu kończą Passę.",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "Do 2 zamrożeń w zapasie, jedno co 4 tygodnie z treningiem. Pokryć da się nawet dwa opuszczone tygodnie z rzędu.",
  "Change the freeze rule": "Zmień zasadę zamrożeń",
  "Every 4th week you train earns a freeze. You can bank 1.": "Co 4. tydzień z treningiem daje zamrożenie. Możesz mieć w zapasie 1.",
  "Every week counts. Miss one and the streak starts over.": "Każdy tydzień się liczy. Opuścisz jeden i Passa zaczyna się od nowa.",
  "From now on: {0}.": "Od teraz: {0}.",
  "From the week of {0} on: {1}.": "Od tygodnia {0}: {1}.",
  "Generous": "Hojna",
  "Gentle": "Łagodna",
  "How forgiving should your week streak be?": "Jak wyrozumiała ma być twoja tygodniowa Passa?",
  "How strict should your streak be?": "Jak surowa ma być twoja Passa?",
  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "Opuścisz tydzień? Pokryje go zamrożenie: Passa trwa dalej, a ten tydzień po prostu nic nie dodaje. Po dwóch opuszczonych tygodniach z rzędu Passa zaczyna się od nowa.",
  "No freezes": "Bez zamrożeń",
  "No freezes on your rule. Every week counts.": "Twoja zasada nie ma zamrożeń. Każdy tydzień się liczy.",
  "No freezes on your rule: a week without a workout starts it over.": "Twoja zasada nie ma zamrożeń: tydzień bez treningu i Passa zaczyna się od nowa.",
  "No workout, and your rule has no freezes, so the streak started over.": "Nie było treningu, a twoja zasada nie ma zamrożeń, więc Passa zaczęła się od nowa.",
  "Weeks already counted stay as they are.": "Już policzone tygodnie zostają bez zmian.",
  "You can change it later in Settings. A change counts from then on.": "Możesz to później zmienić w Ustawieniach. Zmiana działa od tej chwili.",
  "Your rule right now: {0}.": "Twoja zasada teraz: {0}.",
  "Your streak counts weeks with at least one workout. Freezes can cover the odd missed week.": "Passa liczy tygodnie z co najmniej jednym treningiem. Zamrożenia mogą pokryć sporadycznie opuszczony tydzień.",
  "{0} since the week of {1}.": "{0} od tygodnia {1}.",
  "This phone has no print service. Turn one on in its settings and try again.": "Ten telefon nie ma usługi drukowania. Włącz ją w ustawieniach telefonu i spróbuj ponownie.",
  "{0} per side on a {1} bar": "{0} na stronę, gryf {1}",
  "Lighter than the {0} bar": "Lżej niż sam gryf ({0})",
  "Hidden for today. Back tomorrow.": "Ukryte na dziś. Wróci jutro.",
