  "That did not work. Try again in a moment.": "Nie udało się. Spróbuj za chwilę.",
  "That file can never be shared here. Pictures and animations from the built-in library are licensed.": "Tego pliku nigdy nie można tu udostępnić. Obrazy i animacje z wbudowanej biblioteki są licencjonowane.",
  "That file still carries hidden details like a location. Add it again in the app and share the new copy.": "Ten plik wciąż zawiera ukryte dane, np. lokalizację. Dodaj go ponownie w aplikacji i udostępnij nową kopię.",
  "That is not shared any more.": "To nie jest już udostępniane.",
  "That one is not in the community any more.": "Tego nie ma już w społeczności.",
  "That one is yours.": "To jest twoje.",
  "That sound did not come through.": "Ten dźwięk nie dotarł.",
  "That tip did not come through.": "Ta wskazówka nie dotarła.",
  "The sharing text changed. Have a quick read and try again.": "Tekst o udostępnianiu się zmienił. Rzuć na niego okiem i spróbuj ponownie.",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "To jest publiczne dla wszystkich na tym serwerze: każdy, kto ma tu konto, może to zobaczyć, wypróbować i skopiować. Zawsze widać przy tym twoje imię i datę. Udostępniaj tylko to, co twoje: coś twojego autorstwa, twoje nagranie albo coś, co masz prawo przekazać dalej. Obrazy i animacje ćwiczeń z wbudowanej biblioteki są licencjonowane i nigdy nie można ich udostępniać. W każdej chwili możesz przestać udostępniać – kopie, które inni już pobrali, zostają u nich.",
  "This kind of item cannot be taken.": "Tego rodzaju rzeczy nie można wziąć.",
  "This server has no community library.": "Ten serwer nie ma biblioteki społeczności.",
  "Tick that it is yours to share first.": "Najpierw zaznacz, że możesz to udostępnić.",
