  "Make my calendar link": "Utwórz link do kalendarza",
  "New link made. The old one is gone.": "Nowy link gotowy. Stary już nie działa.",
  "Nextcloud or any WebDAV folder, once a day": "Nextcloud lub dowolny folder WebDAV, raz dziennie",
  "No backup yet": "Nie ma jeszcze kopii",
