  // --- Settings → Garmin (garmin-146) ---
  "This version of Habcore Gym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "Ta wersja Habcore Gym nie ma połączenia z Garminem, bo część po stronie Garmina nie jest open source. Mają je wersje z App Store, Google Play i GitHuba.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "Na tym telefonie nie ma Garmin Connect. Zainstaluj go, sparuj tam zegarek i wróć tutaj.",
  "Garmin Connect needs an update before Habcore Gym can talk to your watch.": "Zaktualizuj Garmin Connect, żeby Habcore Gym mógł połączyć się z zegarkiem.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Nie udało się połączyć z Garmin Connect. Spróbuj za chwilę.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Wybierz swojego Garmina w Garmin Connect, a treningi pojawią się na nadgarstku.",
  "Your Garmin isn’t in reach right now. Bring it close with Bluetooth on, and this page catches up by itself.": "Twój Garmin jest teraz poza zasięgiem. Zbliż go z włączonym Bluetooth, a ta strona sama się zaktualizuje.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connect nie zna jeszcze żadnego zegarka. Najpierw sparuj tam swój.",
  "Habcore Gym is on your Garmin. Sets you log on the wrist land here.": "Habcore Gym jest na twoim Garminie. Serie zapisane na nadgarstku trafiają tutaj.",
  "Habcore Gym is on your Garmin. It catches up as soon as the watch is in reach.": "Habcore Gym jest na twoim Garminie. Nadrobi wszystko, gdy tylko zegarek będzie w zasięgu.",
  "Your Garmin is here, Habcore Gym isn’t on it yet. Get it, then open it once on the watch.": "Twój Garmin jest w zasięgu, ale nie ma jeszcze na nim Habcore Gym. Pobierz aplikację i otwórz ją raz na zegarku.",
  "Not in reach": "Poza zasięgiem",
  "Habcore Gym isn’t on it yet": "Nie ma na nim jeszcze Habcore Gym",
  "Your Garmins": "Twoje Garminy",
  "Choose watches": "Wybierz zegarki",
  "Look again": "Szukaj ponownie",
  "Get Habcore Gym for Garmin": "Pobierz Habcore Gym na Garmina",
  "Start a workout on the phone and your Garmin asks to open Habcore Gym.": "Zacznij trening na telefonie, a Garmin zapyta, czy otworzyć Habcore Gym.",
