  "Every single week. That is a habit, not a phase.": "Każdy tydzień, bez wyjątku. To nawyk, nie faza.",
  "Every week you showed up counted.": "Liczył się każdy tydzień, w którym był trening.",
  "Everything aches": "Wszystko boli",
  "Exercise of the month": "Ćwiczenie miesiąca",
  "For the Daily form card in Stats and your check-in. Read on this phone only, never sent anywhere.": "Do karty „Forma dnia” w Statystykach i do twojego check-inu. Dane są odczytywane tylko na tym telefonie i nigdzie nie są wysyłane.",
  "Four taps on sleep, energy, soreness and stress. On a rough day Habcore Gym offers to go lighter, and after a few weeks you see what your good days have in common.": "Cztery dotknięcia: sen, energia, zakwasy i stres. W gorszy dzień Habcore Gym zaproponuje lżejszy trening, a po kilku tygodniach zobaczysz, co łączy twoje dobre dni.",
  "Frazzled": "Duży stres",
  "From Apple Health, read-only, on this phone only.": "Z Apple Zdrowie, tylko do odczytu, tylko na tym telefonie.",
  "From Health Connect, read-only, on this phone only.": "Z Health Connect, tylko do odczytu, tylko na tym telefonie.",
  "Full of beans": "Mnóstwo energii",
  "HRV (RMSSD)": "HRV (RMSSD)",
