  "Insights show up once there is enough to compare: {0} of {1} workouts so far.": "Wnioski pojawią się, gdy będzie dość danych do porównania. Treningi na razie: {0} z {1}.",
  "Just today. This session sits out of progression, so your next targets stay put.": "Tylko dziś. Ten trening nie liczy się do progresji, więc kolejne cele się nie zmienią.",
  "Leaning that way": "Widać tendencję",
  "Lighter day: 10% off the weights. Progression sits this one out.": "Lżejszy dzień: 10% mniej ciężaru. Progresja tym razem pauzuje.",
  "Lighter day: one set fewer per exercise. Progression sits this one out.": "Lżejszy dzień: o jedną serię mniej na ćwiczenie. Progresja tym razem pauzuje.",
  "More than last month. Momentum looks good on you.": "Więcej niż w zeszłym miesiącu. Rozpęd ci służy.",
  "New moves, new muscles asking questions. Curiosity pays.": "Nowe ruchy, nowe mięśnie się odzywają. Ciekawość popłaca.",
  "Not a single week off. Your calendar is impressed.": "Ani jednego wolnego tygodnia. Twój kalendarz jest pod wrażeniem.",
  "Not for me": "Nie dla mnie",
  "Nothing aches": "Nic nie boli",
  "On your good-form days": "W dni dobrej formy",
  "One month, the short version.": "Jeden miesiąc w skrócie.",
  "One set fewer": "O jedną serię mniej",
  "Patterns, not proof. Sleep is rarely the only thing that changed that day.": "Wzorce, nie dowody. Sen rzadko jest jedynym, co zmieniło się tego dnia.",
  "Play your month": "Odtwórz swój miesiąc",
  "Pretty consistent so far": "Na razie dość równo",
