  "Same as {0}. Steady wins.": "Tyle samo co w poprzednim miesiącu ({0}). Regularność wygrywa.",
  "Share my month": "Udostępnij mój miesiąc",
  "Showing up is the whole trick, and you did it.": "Cała sztuka to się pojawiać – i to ci wyszło.",
