  "Sleep": "Sen",
  "Sleep, energy, soreness and stress in four taps before you train. On a rough day it offers to go lighter.": "Sen, energia, zakwasy i stres – cztery dotknięcia przed treningiem. W gorszy dzień zaproponuje lżejszy trening.",
