  "Your call. Nothing changes unless you pick it.": "Twój wybór. Nic się nie zmieni, jeśli tego nie wybierzesz.",
  "Your first month on the books here. Welcome in.": "Twój pierwszy miesiąc z nami. Witaj!",
  "Your month in Habcore Gym": "Twój miesiąc w Habcore Gym",
  "Habcore Gym asks Apple Health for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in Habcore Gym’s own file, and never go to a server.": "Habcore Gym prosi Apple Zdrowie o dostęp do snu, tętna spoczynkowego, zmienności rytmu serca i kroków. Zezwól na to, co chcesz. Dane zostają na tym telefonie, w osobnym pliku Habcore Gym, i nigdy nie trafiają na serwer.",
  "Habcore Gym asks Health Connect for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in Habcore Gym’s own file, and never go to a server.": "Habcore Gym prosi Health Connect o dostęp do snu, tętna spoczynkowego, zmienności rytmu serca i kroków. Zezwól na to, co chcesz. Dane zostają na tym telefonie, w osobnym pliku Habcore Gym, i nigdy nie trafiają na serwer.",
