  "Bodyweight moves from easier to harder. Own every set at the top of the range and the next rung is yours.": "Ćwiczenia z masą ciała od łatwiejszych do trudniejszych. Zrób każdą serię na górze zakresu, a następny szczebel jest twój.",
  "Build a session": "Ułóż trening",
  "Built from the whole library. Pick a gym in Settings to narrow it.": "Ułożony z całej biblioteki. Wybierz siłownię w Ustawieniach, żeby zawęzić.",
  "Built from what “{0}” has.": "Ułożony z tego, co ma „{0}”.",
  "Choose a muscle to see exercises that train it, or build a session from it.": "Wybierz mięsień, żeby zobaczyć ćwiczenia na niego albo ułożyć z nich trening.",
  "Cluster": "Cluster",
  "Core ladder": "Drabinka core",
  "Delete ladder": "Usuń drabinkę",
  "Deload week: {0} of {1} sets, same weight. Lighter on purpose.": "Tydzień deloadu: {0} z {1} serii, ten sam ciężar. Celowo lżej.",
  "Deload week?": "Tydzień deloadu?",
  "Deload weeks": "Tygodnie deloadu",
  "Dip ladder": "Drabinka dipów",
  "Dumbbells only": "Tylko hantle",
  "Easiest first. The Skill ladder rule moves you one rung up when every set hits the top.": "Najłatwiejsze na początek. Zasada „Drabinka umiejętności” przesuwa cię o szczebel wyżej, gdy każda seria dojdzie do górnej granicy zakresu.",
  "Edit ladder": "Edytuj drabinkę",
  "Every set at {0}. You’re ready for the next rung.": "Każda seria na {0}. Czas na następny szczebel.",
  "Every set becomes a cluster: {0} reps in mini-sets of {1}, {2}s to breathe between them, same weight throughout. Heavy work with fewer ugly last reps.": "Każda seria staje się clusterem: {0} powt. w miniseriach po {1}, {2} s na oddech między nimi, cały czas ten sam ciężar. Ciężka robota, mniej koślawych ostatnich powtórzeń.",
  "Every set hit {0}. One more rep each.": "Każda seria osiągnęła {0}. Teraz po jednym powtórzeniu więcej na serię.",
  "Every {0} weeks.": "Co {0} tyg.",
  "Every {0} weeks. Next one: week of {1}.": "Co {0} tyg. Następny: tydzień od {1}.",
  "Everything you picked is still recovering. Here it is anyway, go easy.": "Wszystkie wybrane partie jeszcze się regenerują. Oto trening mimo to – nie przesadzaj.",
  "Excused": "Usprawiedliwiony",
  "Fair enough. Asking again next week.": "Jasne. Zapytamy znowu za tydzień.",
  "For bodyweight skills. One more rep each clean session up to the top of the range, then the next, harder variation of the ladder, back at the bottom.": "Do ćwiczeń z masą ciała. Jedno powtórzenie więcej po każdym czystym treningu aż do górnej granicy zakresu, potem następny, trudniejszy wariant z drabinki – znów od dołu.",
  "Full week it is.": "No to pełny tydzień.",
  "Handstand ladder": "Drabinka stania na rękach",
  "Hinge ladder": "Drabinka zawiasu biodrowego",
  "Hotel room": "Pokój hotelowy",
