  "Sick and travel notes leave the streak to the freezes.": "Notatki o chorobie i podróży nie chronią Passy – zostają tylko zamrożenia.",
  "Sick and travel weeks": "Tygodnie choroby i podróży",
  "Sick or travel notes excused the weeks of {0}.": "Notatki o chorobie lub podróży usprawiedliwiły tygodnie od {0}.",
  "Sick or travelling? Mark a day of that week with a day note and the week is excused, no freeze spent (a few times a year).": "Choroba albo podróż? Oznacz jeden dzień tego tygodnia notatką dnia, a tydzień będzie usprawiedliwiony bez zużycia zamrożenia (kilka razy w roku).",
