  "Swap {0}": "Zamień {0}",
  "The exercises and your history stay. Only the ladder goes.": "Ćwiczenia i twoja historia zostają. Znika tylko drabinka.",
  "Things the list has no word for. Your own exercises that need them show only here.": "Rzeczy, których nie ma na liście. Twoje ćwiczenia, które ich wymagają, widać tylko tutaj.",
  "Three sets, from {0} up to {1} reps. Every set at {1} and the next rung is yours.": "Trzy serie, od {0} do {1} powt. Gdy każda seria dojdzie do {1}, następny szczebel jest twój.",
  "Top of the ladder. Add weight, slow the tempo or make your own next rung.": "Szczyt drabinki. Dodaj ciężar, zwolnij tempo albo zrób własny następny szczebel.",
  "Top rung reached": "Najwyższy szczebel osiągnięty",
  "Train it": "Trenuj",
  "Train {0}": "Trenuj {0}",
  "Twenty-five minutes between the bed and the desk chair.": "Dwadzieścia pięć minut między łóżkiem a krzesłem przy biurku.",
  "When your numbers dip two weeks running (and your check-ins say tired, if you log them), Home asks.": "Gdy twoje wyniki spadają dwa tygodnie z rzędu (a w check-inie zaznaczasz zmęczenie, jeśli go wypełniasz), Start zapyta.",
  "You did it once": "Zrobione raz",
  "You did it {0} times": "Zrobione {0} razy",
  "You were injured, so this week is excused. The streak kept going and no freeze was spent.": "Kontuzja – ten tydzień jest usprawiedliwiony. Passa trwa, a zamrożenie nie zostało zużyte.",
  "You were sick, so this week is excused. The streak kept going and no freeze was spent.": "Choroba – ten tydzień jest usprawiedliwiony. Passa trwa, a zamrożenie nie zostało zużyte.",
  "You were travelling, so this week is excused. The streak kept going and no freeze was spent.": "Podróż – ten tydzień jest usprawiedliwiony. Passa trwa, a zamrożenie nie zostało zużyte.",
  "Your badges": "Twoje odznaki",
  "Your body and the floor. A table for rows, that’s it.": "Ty i podłoga. Stół do wiosłowania i tyle.",
  "Your check-ins say tired, and the numbers are not climbing.": "W check-inie zaznaczasz zmęczenie, a wyniki nie rosną.",
  "Your numbers dipped for two weeks and your check-ins say tired.": "Twoje wyniki spadały przez dwa tygodnie, a w check-inie zaznaczasz zmęczenie.",
  "Your numbers dipped for two weeks running.": "Twoje wyniki spadały dwa tygodnie z rzędu.",
