  "{0}% fewer sets, same weights. Recharge.": "{0}% mniej serii, te same ciężary. Naładuj baterie.",
  "{1} are still recovering, so they sit this one out.": {"one":"{1} wciąż się regeneruje, więc tym razem odpoczywa.","few":"{1} wciąż się regenerują, więc tym razem odpoczywają.","many":"{1} wciąż się regenerują, więc tym razem odpoczywają.","other":"{1} wciąż się regenerują, więc tym razem odpoczywają."},
  "{1} is still recovering, so it sits this one out.": "{1} jeszcze się regeneruje, więc tym razem odpoczywa.",
  "And it stays that way: Habcore Gym Offline has no internet permission, so Android blocks anything it might try.": "I tak zostanie: Habcore Gym Offline nie ma uprawnienia do internetu, więc Android zablokuje każdą próbę połączenia.",
  "Any of the sounds on your phone.": "Dowolny dźwięk z telefonu.",
  "Back it up now and then in Settings, Data & backup. A file on your phone is the only copy there is.": "Co jakiś czas zrób kopię w Ustawieniach → Dane i kopia. Plik na telefonie to jedyna kopia.",
  "Closing the app resets the count; the log never leaves the phone.": "Zamknięcie aplikacji zeruje licznik; dziennik nigdy nie opuszcza telefonu.",
  "Counting since {0}, when the app started. Closing the app resets it; the log never leaves the phone.": "Liczone od {0}, czyli od uruchomienia aplikacji. Zamknięcie aplikacji je zeruje; dziennik nigdy nie opuszcza telefonu.",
  "Each reminder can sound different, so you know which one it is before you look.": "Każde przypomnienie może brzmieć inaczej, więc wiesz, które to, zanim spojrzysz.",
  "Everything this app asked the internet for, newest first. The address only, never what was in it.": "Wszystkie zapytania tej aplikacji do internetu, od najnowszych. Tylko adresy, nigdy treść.",
  "For reading mid-set without your glasses.": "Do czytania w trakcie serii bez okularów.",
  "Larger": "Jeszcze większy",
  "Last at {0}": "Ostatnio o {0}",
  "Latest": "Najnowsze",
  "Less: no sliding, bouncing or snow. Things just appear.": "Mniej: nic nie przesuwa się, nie podskakuje ani nie pada śnieg. Wszystko po prostu się pojawia.",
  "Like the phone": "Jak w telefonie",
  "Mostly your own server, {0}, when there was something to sync.": "Głównie twój własny serwer ({0}), gdy było coś do synchronizacji.",
  "Motion": "Ruch",
  "Network log": "Dziennik sieci",
  "No map search in Habcore Gym Offline. Stand in your gym, tap Current location, done.": "W Habcore Gym Offline nie ma wyszukiwania na mapie. Stań w siłowni, dotknij „Bieżąca lokalizacja” i gotowe.",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "Ani jeden bajt nie opuścił tego telefonu. Twój trening to tylko twoja sprawa.",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "Jeszcze nic. Telefon łączy się z twoim serwerem, gdy jest coś do synchronizacji.",
  "Phone default": "Domyślny w telefonie",
  "Phone sound": "Dźwięk telefonu",
  "Pick a phone sound…": "Wybierz dźwięk z telefonu…",
  "Showing the last {0}. The count above has them all.": "Ostatnie wpisy: {0}. Licznik powyżej obejmuje wszystkie.",
  "Shows up, keeps quiet.": "Pojawia się bez dźwięku.",
  "Tap one to hear it. It rings even with the app closed.": "Dotknij, żeby posłuchać. Zadzwoni nawet przy zamkniętej aplikacji.",
  "Text size": "Rozmiar tekstu",
  "This is Habcore Gym Offline: Android doesn’t even let it on the internet. Want sync? The normal Habcore Gym app can do that, next to this one.": "To Habcore Gym Offline – Android nie wpuszcza go nawet do internetu. Chcesz synchronizacji? Potrafi to zwykła aplikacja Habcore Gym, którą możesz mieć obok tej.",
  "Weigh-ins, measurements and progress photos.": "Ważenia, pomiary i zdjęcia postępów.",
  "Whatever your phone uses for notifications.": "Dźwięk, którego telefon używa do powiadomień.",
  "When you walk into your gym.": "Gdy wchodzisz do swojej siłowni.",
  "Who": "Kto",
  "Who this app talked to since you opened it.": "Z kim ta aplikacja się łączyła od jej otwarcia.",
  "Workout days and the nudge when one slips by.": "Dni treningowe i przypomnienie, gdy któryś przepadnie.",
  "Workout reminders": "Przypomnienia o treningu",
  "Habcore Gym Offline has no internet permission. Your training stays on this phone, full stop.": "Habcore Gym Offline nie ma uprawnienia do internetu. Twój trening zostaje na tym telefonie. Kropka.",
  "Habcore Gym Offline never checks for updates, it can’t. New versions come from wherever you got this one.": "Habcore Gym Offline nie sprawdza aktualizacji – nie może. Nowe wersje znajdziesz tam, skąd masz tę.",
  "Habcore Gym Offline, no internet permission": "Habcore Gym Offline, bez uprawnienia do internetu",
  "Habcore Gym Offline: on this phone, and only here": "Habcore Gym Offline: na tym telefonie i tylko tu",
  "Habcore Gym sounds": "Dźwięki Habcore Gym",
  "{0} request this session": "{0} żądanie w tej sesji",
  "{0} requests this session": {"one": "{0} żądanie w tej sesji", "few": "{0} żądania w tej sesji", "many": "{0} żądań w tej sesji", "other": "{0} żądania w tej sesji"},
  "From the app": "Z aplikacji",
