  // --- WebDAV backup on a shared device (qa2-146) ---
  "This backup belongs to another account": "Ta kopia należy do innego konta",
  "Someone else set it up on this device, so nothing of yours goes to their folder. Disconnect it to set up your own.": "Ktoś inny skonfigurował ją na tym urządzeniu, więc nic twojego nie trafia do jego folderu. Odłącz ją, żeby skonfigurować własną.",
  "Routine from a past workout": "Plan z wcześniejszego treningu",
  "From a past workout": "Z wcześniejszego treningu",
  "Pick one you did, imported ones too. Its exercises and sets become a routine you can tweak.": "Wybierz trening, który już zrobiłeś (także zaimportowany). Jego ćwiczenia i serie staną się planem, który możesz dopracować.",
  "That workout has no exercises to copy.": "Ten trening nie ma ćwiczeń do skopiowania.",
  "Saved as a routine. Your workout stays as it was.": "Zapisano jako plan. Trening zostaje bez zmian.",
  "Nothing logged yet. Train once, or import your history, and it shows up here.": "Nie masz jeszcze zapisanych treningów. Zrób jeden trening albo zaimportuj historię, a pojawią się tutaj.",
  // --- text size and forgotten workouts (watch-polish-146) ---
  "Smallest": "Najmniejszy",
  "Largest": "Największy",
  "Follows your phone’s text size, now {0}.": "Zgodnie z rozmiarem tekstu w telefonie (teraz {0}).",
  "Big enough to read from the bench.": "Wystarczająco duży, żeby czytać z ławki.",
  "Heavy squats, then pizza.": "Ciężkie przysiady, potem pizza.",
  "This is how the app reads now.": "Tak teraz wygląda tekst w aplikacji.",
  "font text size bigger smaller letters": "czcionka tekst rozmiar większy mniejszy litery",
  "forgotten workout auto finish": "zapomniany trening automatyczne zakończenie",
  "Ask “Still training?”": "Pytaj „Jeszcze trenujesz?”",
  "End by itself when I leave the gym": "Zakończ automatycznie, gdy wyjdę z siłowni",
