  "Back in the workout. Pick up where you left off.": "Wracasz do treningu. Kontynuuj od miejsca przerwania.",
  "Ended by itself when you left the gym": "Zakończony automatycznie po wyjściu z siłowni",
  "Ended by itself after a quiet spell": "Zakończony automatycznie po dłuższej bezczynności",
  "Saved as ending at {0}, after your last set and its rest.": "Zapisany z godziną zakończenia {0} – po ostatniej serii i jej przerwie.",
  "Reopen workout": "Otwórz trening ponownie",
  "Still training?": "Jeszcze trenujesz?",
  "No set for {0} minutes. If you’re done, I’ll wrap it up in {1} minutes, ending at your last set.": "Brak serii od {0} min. Jeśli to koniec, zakończę trening za {1} min z godziną ostatniej serii.",
  "Looks like you left the gym": "Wygląda na to, że nie ma cię już na siłowni",
  "Finish the workout now? Otherwise it ends by itself in {0} minutes.": "Zakończyć trening teraz? Inaczej skończy się sam za {0} min.",
  "Keep going": "Trenuję dalej",
  "Finish now": "Zakończ teraz",
  "Finish the workout now? Otherwise it ends by itself at {0}.": "Zakończyć trening teraz? Inaczej skończy się sam o {0}.",
  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "Od dłuższej chwili nic nie zapisujesz. Jeśli to koniec, trening zakończy się sam o {0}, z godziną ostatniej serii.",
  "Forgotten workouts": "Zapomniane treningi",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "Jeśli nikt nie odpowie, trening zakończy się sam i niczego nie usunie. Koniec to ostatnia seria plus jej przerwa, więc czas się zgadza. Przez jeden dzień możesz go ponownie otworzyć z Historii. Zegarek też zapyta.",
  "Never asks and never ends one by itself.": "Nigdy nie pyta i nigdy sam nie kończy treningu.",
  "The default. Long enough for a chat at the water fountain.": "Domyślnie. Wystarczy na pogawędkę przy dystrybutorze wody.",
  "Asks the moment your phone walks out of your gym, then wraps up.": "Pyta, gdy tylko wyjdziesz z telefonem z siłowni, a potem kończy trening.",
  "Needs the gym reminder: {0}.": "Wymaga przypomnienia o siłowni: {0}.",
  "Save to Photos": "Zapisz w Zdjęciach",
