  "Saved to Photos": "Zapisano w Zdjęciach",
  "Could not save the picture.": "Nie udało się zapisać obrazu.",
  "Habcore Gym may not add pictures to Photos. You can allow it in the phone settings.": "Habcore Gym nie ma uprawnień do dodawania obrazów do Zdjęć. Możesz na to zezwolić w ustawieniach telefonu.",
