  "In the app": "W aplikacji",
  "Lifter": "Siłownia",
  "Live widget": "Widżet na żywo",
  "Lock Screen": "Ekran blokady",
  "Lock Screen, notification, the workout card": "Ekran blokady, powiadomienie, karta treningu",
  "Long-press view": "Widok po długim naciśnięciu",
  "Minimal": "Minimalny",
  "Needs iOS 17 or later. No animations on the Lock Screen, so the exercise picture is a still. Buttons work without unlocking, Finish opens the app.": "Wymaga iOS 17 lub nowszego. Na ekranie blokady nie ma animacji, więc obraz ćwiczenia jest nieruchomy. Przyciski działają bez odblokowania, „Zakończ” otwiera aplikację.",
  "No buttons. A tap on it opens Habcore Gym.": "Bez przycisków. Dotknięcie otwiera Habcore Gym.",
  "No room on the Lock Screen. Apple keeps Live Activities to about 160 points tall.": "Na ekranie blokady nie ma już miejsca. Apple ogranicza wysokość Aktywności na żywo do ok. 160 punktów.",
  "No tiles yet.": "Nie ma jeszcze kafelków.",
  "Nothing here yet, so the workout screen stays as it is. Add a tile or pick a preset.": "Na razie nic tu nie ma, więc ekran treningu zostaje bez zmian. Dodaj kafelek albo wybierz szablon.",
  "Opens Habcore Gym, since saving asks what to keep.": "Otwiera Habcore Gym, bo przy zapisie trzeba wybrać, co zachować.",
  "Six tiles fit in a notification before it starts mumbling.": "W powiadomieniu mieści się sześć kafelków – więcej byłoby nieczytelne.",
  "Size of {0}": "Rozmiar: {0}",
  "The Dynamic Island holds four tiles. It is an island, not a continent.": "Dynamic Island mieści cztery kafelki. To wyspa, nie kontynent.",
  "The pill": "Pigułka",
  "The pill has two spots, one each side of the camera.": "Pigułka ma dwa miejsca, po jednym z każdej strony aparatu.",
  "The pill shows two tiles beside the camera. Long-press it for the rest.": "Pigułka pokazuje dwa kafelki przy aparacie. Przytrzymaj ją, żeby zobaczyć resztę.",
  "The widget fits three lines under the set.": "Widżet mieści trzy wiersze pod serią.",
  "Three buttons fit in the Dynamic Island.": "W Dynamic Island mieszczą się trzy przyciski.",
  "Tiles": "Kafelki",
  "Tiles become lines of text, so Android 16 can keep it a Live Update by the clock. While a rest runs, the notification shows its rest buttons.": "Kafelki stają się wierszami tekstu, żeby Android 16 mógł pokazywać powiadomienie jako Live Update przy zegarze. W czasie przerwy powiadomienie pokazuje przyciski przerwy.",
  "Up to three lines under the set. The widget keeps its own − and + buttons.": "Do trzech wierszy pod serią. Widżet zachowuje własne przyciski − i +.",
  "Where it shows": "Gdzie się pokazuje",
  "Work set": "Seria robocza",
  "Zone {0}": "Strefa {0}",
  "{0} layout on.": "Szablon {0} włączony.",
  "Exercise picture": "Obraz ćwiczenia",
  "Target": "Cel",
  "Incline": "Nachylenie",
  "Resistance": "Opór",
  "Band": "Guma",
  "Superset partner": "Partner w superserii",
  "Record hint": "Wskazówka o rekordzie",
  "Time since start": "Czas od startu",
  "Clock": "Zegar",
  "Heart-rate zone": "Strefa tętna",
  "Workout name": "Nazwa treningu",
  "Less weight": "Mniej ciężaru",
  "More weight": "Więcej ciężaru",
  "One rep less": "O powtórzenie mniej",
  "One rep more": "O powtórzenie więcej",
