  "Previous exercise": "Poprzednie ćwiczenie",
  // --- AI Coach 1.4.5: setup, actions, data switches, connector (coach-146) ---
  "Add it as a custom connector in Claude or ChatGPT and sign in with Habcore Gym when it asks. Other assistants take a token from below.": "Dodaj go jako własny łącznik w Claude lub ChatGPT i zaloguj się przez Habcore Gym, gdy pojawi się prośba. Inni asystenci korzystają z tokenu poniżej.",
  "Add “{0}” to my plan": "Dodaj „{0}” do mojego planu",
  "Add “{0}” to your exercises": "Dodaj „{0}” do swoich ćwiczeń",
  "Added to your exercises": "Dodano do twoich ćwiczeń",
  "After you say yes, it goes back to {0}. Only say yes if you just started this there.": "Gdy się zgodzisz, nastąpi powrót do {0}. Zgódź się tylko, jeśli przed chwilą rozpoczęto to właśnie tam.",
  "Back to Habcore Gym": "Wróć do Habcore Gym",
  "Choose what it may read, and whether it may search the web": "Wybierz, co może czytać i czy może szukać w sieci",
  "Claude, with an API key": "Claude z kluczem API",
  "Code from OpenRouter": "Kod z OpenRoutera",
  "Daily check-ins, sleep, resting heart rate, HRV and steps from your phone, and blood pressure. Off until you switch it on.": "Codzienne check-iny, sen, tętno spoczynkowe, HRV i kroki z telefonu oraz ciśnienie. Wyłączone, dopóki tego nie włączysz.",
  "Estimated one-rep maxes of your main lifts over the last twelve weeks.": "Szacowane 1RM głównych ćwiczeń z ostatnich dwunastu tygodni.",
  "Find it for me": "Znajdź to dla mnie",
  "For questions that need facts from outside your training, like a study or a product.": "Do pytań wymagających faktów spoza twojego treningu, np. o badanie czy produkt.",
  "From the routines library": "Z biblioteki planów",
  "GPT, with an API key": "GPT z kluczem API",
  "Gemini, with a free tier to start": "Gemini z darmowym limitem na start",
  "Get a key from {0}": "Pobierz klucz z {0}",
  "Health and how you feel": "Zdrowie i samopoczucie",
  "How it’s done": "Jak to zrobić",
  "It shows up under Settings → API tokens, where you can revoke it any time.": "Pojawi się w Ustawieniach → Tokeny API, gdzie możesz go w każdej chwili odwołać.",
  "Looks for Ollama, LM Studio and llama.cpp on the machine running your Habcore Gym server and on this phone.": "Szuka Ollamy, LM Studio i llama.cpp na maszynie z twoim serwerem Habcore Gym i na tym telefonie.",
  "Nothing answered. Type its address below, like http://192.168.1.20:11434.": "Nic nie odpowiedziało. Wpisz adres poniżej, np. http://192.168.1.20:11434.",
  "Ollama or LM Studio at home, nothing leaves your Wi-Fi": "Ollama lub LM Studio w domu, nic nie wychodzi poza twoje Wi-Fi",
  "On my network": "W mojej sieci",
  "One sign-in for Claude, GPT, Gemini and more": "Jedno logowanie do Claude, GPT, Gemini i innych",
  "OpenRouter makes a key just for this phone, billed to your OpenRouter credits. You can revoke it there any time.": "OpenRouter tworzy klucz tylko dla tego telefonu, rozliczany z twoich kredytów OpenRouter. Możesz go tam w każdej chwili odwołać.",
  "Or paste a key": "Albo wklej klucz",
  "Paste a code instead": "Wklej zamiast tego kod",
  "Pick your AI": "Wybierz swoją AI",
  "Remember": "Zapamiętaj",
  "Remember this": "Zapamiętaj to",
  "Saved to what the Coach knows about you": "Zapisane w tym, co Trener o tobie wie",
  "Search the web": "Szukaj w sieci",
  "Should the Coach remember this?": "Czy Trener ma to zapamiętać?",
  "Sign in with OpenRouter": "Zaloguj się przez OpenRouter",
  "Signed in with OpenRouter": "Zalogowano przez OpenRouter",
  "Sources": "Źródła",
  "Start it again from the assistant. It only waits ten minutes.": "Zacznij od nowa w asystencie. Czeka tylko dziesięć minut.",
  "Start “{0}” now": "Zacznij „{0}” teraz",
  "Start “{0}” now?": "Zacząć „{0}” teraz?",
  "Strength trends": "Postępy siły",
  "Switched off, it is left out of every request from now on.": "Po wyłączeniu nie będzie już dołączane do żadnego zapytania.",
  "Test it": "Sprawdź",
  "That doesn’t look like a code from OpenRouter.": "To nie wygląda na kod z OpenRoutera.",
  "That looks like a {0} key, so I switched to {0}.": "To wygląda na klucz {0}, więc przełączono na {0}.",
  "That plan isn’t in the library any more.": "Tego planu nie ma już w bibliotece.",
  "That routine is gone.": "Tego planu już nie ma.",
  "The Coach needs these to plan anything at all.": "Bez tego Trener niczego nie zaplanuje.",
  "The OpenRouter sign-in did not work: {0}": "Nie udało się zalogować przez OpenRouter: {0}",
  "The connection to the AI provider dropped while the Coach was thinking. Try again, ideally on Wi-Fi.": "Połączenie z dostawcą AI zerwało się, gdy Trener myślał. Spróbuj jeszcze raz, najlepiej przez Wi-Fi.",
  "The connection to your AI provider dropped while the Coach was thinking. Try again, ideally on Wi-Fi.": "Połączenie z twoim dostawcą AI zerwało się, gdy Trener myślał. Spróbuj jeszcze raz, najlepiej przez Wi-Fi.",
  "This sign-in has expired": "To logowanie wygasło",
  "Use code": "Użyj kodu",
  "Web research": "Wyszukiwanie w sieci",
  "What the Coach sees": "Co widzi Trener",
  "You decide": "Ty decydujesz",
  "Your AI provider has no web search.": "Twój dostawca AI nie ma wyszukiwania w sieci.",
  "Your latest measurements and the ones from about eight weeks before.": "Twoje najnowsze pomiary i te sprzed około ośmiu tygodni.",
  "Your provider may charge a little per search. The pages it read are linked under its answer.": "Twój dostawca może doliczać drobną opłatę za wyszukiwanie. Przeczytane strony są podlinkowane pod odpowiedzią.",
  "Your server’s admin hasn’t switched this on.": "Administrator twojego serwera tego nie włączył.",
  "free": "za darmo",
  "this plan": "ten plan",
  "this routine": "ten plan treningowy",
  "{0} wants to use your Habcore Gym": "{0} chce korzystać z twojego Habcore Gym",
  "It works! {0} model to pick from.": "Działa! Do wyboru {0} model.",
  "It works! {0} models to pick from.": {"one": "Działa! Do wyboru {0} model.", "few": "Działa! Do wyboru {0} modele.", "many": "Działa! Do wyboru {0} modeli.", "other": "Działa! Do wyboru {0} modelu."},
